INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1133980', 1133980, 'Danny Lau Dan', '/gEmCCnMg9GvskUPSuGQA3ae8irk.jpg', 'Acting', '1945-12-18', 'Weihai, Shandong, China', 'Liu Tan was born in Shanghai in 1945 and moved with his family to Hong Kong five years later. In 1968, Liu entered the actor training class run by Cathay Film Organisation and was signed up by the studio after graduated. Liu started his career in supporting roles until he got his big break in "An Apple A Day" in 1970. Liu moved to Shaw Brothers in 1971 and among the movies he appeared in "The Devil''s Mirror" and "The Warlord". Liu left Shaw Brothers in 1972 to concentrate predominantly on voice dubbing while he still making sporadic appearance in films. In 1977, Liu joined TVB as a contract actor. His acclaimed role was as the villain in the classic series "The Bund". For the past two decades, Liu has made regular appearance in TVB and he was one of the popular artists in Hong Kong. -- From the Celestial DVD release of "The Devil''s Mirror".', 'nm0490623', 1791590954, 1791590954);
