INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-118545', 118545, 'Dakota Johnson', '/qFek0KqpaPV5mVyHHNfAapDE9Tj.jpg', 'Acting', '1989-10-04', 'Austin, Texas, USA', 'Dakota Mayi Johnson (born October 4, 1989) is an American actress. The daughter of actors Don Johnson and Melanie Griffith, Johnson made her film debut at age ten with a minor role in Crazy in Alabama (1999), directed by her then-stepfather Antonio Banderas and starring her mother. After graduating from high school, she began auditioning for roles and had a minor part in The Social Network (2010). Johnson had her breakthrough playing the lead role in the erotic Fifty Shades film series (2015–2018). In 2016, she received a BAFTA Rising Star Award nomination and was featured in a Forbes 30 Under 30 list.

Her profile grew with roles in the crime drama Black Mass (2015), the drama A Bigger Splash (2015), the romantic comedy How to Be Single (2016), the horror film Suspiria (2018), the thriller Bad Times at the El Royale (2018), the coming-of-age film The Peanut Butter Falcon (2019), the psychological drama The Lost Daughter (2021), the romantic drama Cha Cha Real Smooth (2022), and the superhero film Madame Web (2024).

Description above from the Wikipedia article Dakota Johnson, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0424848', 1791590954, 1791590954);
