INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1813', 1813, 'Anne Hathaway', '/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg', 'Acting', '1982-11-12', 'Brooklyn, New York City, New York, USA', 'Anne Jacqueline Hathaway (born November 12, 1982) is an American actress. She has received numerous accolades, most notably an Academy Award for Best Supporting Actress, a Golden Globe, a BAFTA Award, and a Screen Actors Guild Award for her performance as Fantine in Les Misérables (2012). In 2015, she was one of the highest-paid actresses in the world, and in 2024, she was included on Time magazine''s list of the 100 most influential people. Additionally, she holds a Primetime Emmy Award for her voice work on The Simpsons.

​She began her career appearing in the television series Get Real (1999) before achieving worldwide fame as the lead in her film debut, the Disney comedy The Princess Diaries (2001). She earned critical acclaim for her transition to more adult roles in the dramas Havoc and Brokeback Mountain in 2005. Her star status was solidified with the commercial success of The Devil Wears Prada (2006), starring alongside Meryl Streep, and she received her first Oscar nomination for her role as a woman in rehab in Rachel Getting Married (2008).

​Since 2010, she has starred in several of her career''s biggest box-office hits, including the romantic comedies Valentine''s Day (2010) and Love and Other Drugs (2010), the fantasy film Alice in Wonderland (2010), and her role as Catwoman in The Dark Knight Rises (2012). Her films Interstellar (2014), The Intern (2015), Ocean''s 8 (2018), The Idea of You (2024), and the most recent The Odyssey (2026) have reaffirmed her versatility in the industry. Beyond her artistic work, she serves as a UN Women Goodwill Ambassador, advocating for gender equality and women''s rights in the workplace.', 'nm0004266', 1791590954, 1791590954);
