INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2299', 2299, 'Josh Hartnett', '/8nTEioiir92fGHcASarPxkjF6kG.jpg', 'Acting', '1978-07-21', 'Saint Paul, Minnesota, USA', 'Joshua Daniel "Josh" Hartnett (born July 21, 1978) is an American actor and producer.

He first came to audiences'' attention in 1997 as "Michael Fitzgerald" in the crime television series Cracker. He made his feature film debut in 1998, co-starring with Jamie Lee Curtis in Halloween H20: 20 Years Later. That same year, he received an MTV Movie Award nomination for Best Breakthrough Male Performance. Hartnett gained fame for his role as Cpt Danny Walker in Pearl Harbor, and has starred since then for a variety of well-known directors such as Ridley Scott, Brian De Palma, Robert Rodriguez, Tran Anh Hung and Michael Bay.', 'nm0001326', 1791590954, 1791590954);
