INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1100144', 1100144, 'Ismael Cruz Cordova', '/oXcrsQGndk60iFkNB8qFnMHlNzL.jpg', 'Acting', '1987-04-07', 'Aguas Buenas, Puerto Rico', 'Ismael Cruz Córdova (born April 7, 1987) is an actor, entrepreneur currently based in New York. Born and raised in Aguas Buenas, Puerto Rico. At age fifteen, Ismael began working locally in commercials, TV and film shortly after joining his High School Drama Club. In 2006 he decided to further pursue his dream and moved to New York City where he studied at NYU''s Tisch Shcool of the Arts. in NYC Ismael has been recognized for his acting work with several awards and critical acclaim named one of the 25 Leaders of the future by Latino Leaders Magazine, and awarded a VOCES de Ford Award by Ford Motors, which is given to trailblazing exemplary Individuals in the media and entertainment Industry.', 'nm3033454', 1791590954, 1791590954);
