INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1429011', 1429011, 'Irina Dvorovenko', '/kVgnALw6PnmzTE5PeFIGfaZXo2j.jpg', 'Acting', '1973-08-28', 'Kiev, USSR [now Ukraine]', 'Irina Vladimirovna Dvorovenko, born August 28, 1973, is a Ukrainian-American retired ballet dancer and actress, known for her roles in Flesh & Bone and The Americans. She was a principal dancer with the American Ballet Theatre.

Dvorovenko was born in Kiev, Ukraine during the Soviet period. Her parents are dancers. She started with gymnastics before entering the Kiev Ballet School at the age of ten.', 'nm6262044', 1791590954, 1791590954);
