INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-71889', 71889, 'Michael Abbott Jr.', '/af4hYV7WwEtL48eND0xDsdobJq9.jpg', 'Acting', '1978-07-08', 'Tennessee, USA', 'Michael Abbott Jr. (born July 8, 1978) is an American actor. Abbott Jr. is an East Tennessee native and a graduate of The North Carolina School of the Arts Drama School. He has appeared in numerous stage productions in New York City and in productions across the country in some of the nations most prestigious regional theaters. He is also a proud member of John Houseman''s Tony-honored, Acting Company. He made his feature film debut in writer and director Jeff Nichol''s debut feature film Shotgun Stories in 2007.', 'nm2534638', 1791590954, 1791590954);
