INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1136406', 1136406, 'Tom Holland', '/adwEBb2sCSzqwnpVgNEG7irl1Ne.jpg', 'Acting', '1996-06-01', 'Kingston-upon-Thames, London, England', 'Thomas Stanley Holland (born 1 June 1996) is an English actor. His accolades include a BAFTA Award as well as two Critics'' Choice Awards nominations. His films as a lead actor have grossed over $9.9 billion worldwide. He was featured on the Forbes 30 Under 30 Europe list of 2019.

Holland began his career as a teen when he played a supporting role and later the title role in Billy Elliot the Musical on the West End from 2008 to 2010. He made his film debut in the disaster drama The Impossible (2012) followed by roles in the romance drama How I Live Now (2013) and the historical adventure dramas In the Heart of the Sea (2015) and The Lost City of Z (2016).

Holland achieved international recognition playing Peter Parker/Spider-Man in six Marvel Cinematic Universe (MCU) superhero films, beginning with Captain America: Civil War (2016). The following year, Holland received the BAFTA Rising Star Award and became the youngest actor to play a title role in an MCU film in Spider-Man: Homecoming. Its sequels, Far From Home (2019) and No Way Home (2021), each grossed more than $1 billion worldwide; the latter became the highest-grossing film of the year. Holland played against-type roles in the crime dramas The Devil All the Time (2020) and Cherry (2021), and starred in the big-budget films Uncharted (2022) and The Odyssey (2026).

Holland has voiced roles in the animated features Spies in Disguise (2019) and Onward (2020). On television, he took roles in the PBS historical miniseries Wolf Hall (2015) and the Apple TV+ psychological thriller limited series The Crowded Room (2023). He returned to the stage starring as one of the title roles in the West End revival of Romeo and Juliet (2024). He is married to his longtime co-star Zendaya.

Description above from the Wikipedia article Tom Holland, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm4043618', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-969681-cast-0', 'tmdb-movie-969681', 'tmdb-person-1136406', 'Peter Parker / Spider-Man', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1590797', 1590797, 'Sadie Sink', '/fV0KHJcK3fYX2acMorDUf1Uv9mY.jpg', 'Acting', '2002-04-16', 'Brenham, Texas, USA', 'Sadie Elizabeth Sink (born April 16, 2002) is an American actress. She began her career in theatre as a child, playing the title role in the musical Annie (2012–2014) and young Elizabeth II in the historical play The Audience (2015) on Broadway. In 2016, she made her film debut in the biographical sports drama Chuck. Sink broke through as Max Mayfield in the Netflix science fiction horror series Stranger Things (2017–2025), earning critical praise for her performance.

Sink appeared in the horror film trilogy Fear Street in 2021 and starred in Darren Aronofsky''s 2022 psychological drama The Whale. She portrays Jean Grey in the Marvel Cinematic Universe(MCU), starting with the film Spider-Man: Brand New Day (2026), and will reprise the role in Avengers: Secret Wars (2027) and the untitled X-Men film (2028). She received a Tony Awardnomination for Best Actress in a Play for her performance in the Broadway production of John Proctor Is the Villain (2025), and made her West End debut in Robert Icke''s production of Romeo and Juliet in 2026.

Description above from the Wikipedia article Sadie Sink, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm5584750', 1791590954, 1791590954);
