INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2028037', 2028037, 'Tramell Tillman', '/bEA15zMnkcXlRroYjKrFUWiiK7y.jpg', 'Acting', '1985-06-17', 'Washington, D.C., USA', 'Tramell Tillman (/trəˈmɛl/ trə-MEL; born June 17, 1985) is an American actor. He is known for his role as Seth Milchick in the Apple TV+ series Severance (2022–present), for which he received his first Primetime Emmy nomination for Outstanding Supporting Actor in a Drama Series in 2025.

