INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-505710', 505710, 'Zendaya', '/qGkBlyn1AwQpuFnRARMRwj0iHZp.jpg', 'Acting', '1996-09-01', 'Oakland, California, USA', 'Zendaya Maree Stoermer Coleman (born September 1, 1996), known mononymously as Zendaya, is an American actress. Her accolades include two Primetime Emmy Awards and a Golden Globe. In 2022, Time named her one of the 100 most influential people in the world.

Born in Oakland, California, Zendaya began her career as a child model and dancer before gaining prominence for her roles on the Disney Channel sitcoms Shake It Up (2010–2013) and K.C. Undercover (2015–2018), the latter of which she also produced. For her performance as Rue Bennett, a struggling drug-addicted teenager in the HBO teen drama series Euphoria (2019–2026), Zendaya won two Primetime Emmy Awards for Outstanding Lead Actress in a Drama Series.

Zendaya made her feature film debut as MJ in the Marvel Cinematic Universe film Spider-Man: Homecoming (2017). She reprised her role in its sequels Far From Home (2019), No Way Home (2021), and Brand New Day (2026). She has since starred in the musical film The Greatest Showman (2017), Denis Villeneuve''s Dune trilogy (2021–2026), Christopher Nolan''s epic The Odyssey (2026), and earned praise for her performances in the romance films Malcolm & Marie (2021), Challengers (2024) and The Drama (2026).', 'nm3918035', 1791590954, 1791590954);
