INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-19498', 19498, 'Jon Bernthal', '/bjcglF1IpDcZNs1HwFxakGpzBo6.jpg', 'Acting', '1976-09-20', 'Washington, District of Columbia, USA', 'Jonathan Edward Bernthal (/ˈbɜːrnθɔːl/; born September 20, 1976) is an American actor. He came to prominence for portraying Shane Walsh on the AMC horror drama series The Walking Dead (2010–2012; 2018), where he was a starring cast member in the first two seasons. Bernthal achieved further recognition as Frank Castle/The Punisher in the Marvel Cinematic Universe, appearing in the second season of Daredevil (2016), the spin-off series The Punisher (2017–2019), and the revival series Daredevil: Born Again (2025–present), and Spider-Man: Brand New Day (2026). For his recurring guest role as restaurant owner Michael Berzatto in the series The Bear (2022–present), he won a Primetime Emmy Award. 

His film roles include Snitch (2013), The Wolf of Wall Street (2013), Fury (2014), Sicario (2015), The Accountant (2016),  Baby Driver (2017), Wind River (2017), Widows (2018), Ford v Ferrari (2019), King Richard, The Many Saints of Newark (both 2021), Origin (2023), The Accountant 2 (2025), and The Odyssey (2026)

Description above from the Wikipedia article Jon Bernthal, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1256532', 1791590954, 1791590954);
