INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3141', 3141, 'Marisa Tomei', '/vAQ10fvGfVyuJdMNKVMA4ZkacWL.jpg', 'Acting', '1964-12-04', 'Brooklyn, New York City, New York, USA', 'Marisa Tomei (/toʊˈmeɪ/, Italian: [toˈmɛi]; born December 4, 1964) is an American actress. She gained prominence for her comedic performance in My Cousin Vinny (1992), for which she won the Academy Award for Best Supporting Actress. She received further nominations in the category for In the Bedroom (2001) and The Wrestler (2008). 

Her early appearances were in the soap opera As the World Turns (1983–1985) and the first season of the sitcom A Different World (1987). Tomei''s other notable films include Chaplin (1992), The Paper (1994), What Women Want (2000), Danika (2006), Before the Devil Knows You''re Dead (2007), Wild Hogs (2007), The Wrestler (2008), The Ides of March (2011), Crazy, Stupid, Love (2011), Parental Guidance (2012), The Big Short (2015), and The King of Staten Island (2020). She also portrayed May Parker in the Marvel Cinematic Universe, from Captain America: Civil War (2016) to Spider-Man: No Way Home (2021).

Tomei was a founding member of the Naked Angels Theater Company. She appeared in John Morgan Evans'' Daughters (1986) off-Broadway before making her Broadway debut in Wait Until Dark opposite Quentin Tarantino (1998). She earned a nomination for the Drama Desk Award for Outstanding Featured Actress in a Play for her role in Top Girls (2008), and a special Drama Desk Award for Will Eno''s The Realistic Joneses (2014). She returned to Broadway in the revival of The Rose Tattoo in 2019.

Description above from the Wikipedia article Marisa Tomei, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000673', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-969681-cast-9', 'tmdb-movie-969681', 'tmdb-person-3141', 'May Parker', 9);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3489', 3489, 'Naomi Watts', '/7ysvff7ZhW388SIh2YjQ0XIryOn.jpg', 'Acting', '1968-09-28', 'Shoreham, Kent, England, UK', 'Naomi Ellen Watts (born September 28, 1968) is a British actress. She has been nominated for two Academy Awards for Best Actress for her performances as a grief-stricken mother in Alejandro González Iñárritu''s film 21 Grams (2003), and as Maria Bennett in the disaster film The Impossible (2012).

After her family moved to Australia, she made her film debut there in the drama For Love Alone (1986) and then appeared in three television series, Hey Dad..! (1990), Brides of Christ (1991), and Home and Away (1991), and the film Flirting (1991). After moving to the United States, she initially struggled as an actress, taking roles in small-scale films until she starred in David Lynch''s psychological thriller Mulholland Drive in 2001 as an aspiring actress. This role started her rise to international prominence.

She has served as an ambassador for the Joint United Nations Programme on HIV/AIDS and Pantene''s Beautiful Lengths.

​From Wikipedia, the free encyclopedia.', 'nm0915208', 1791590954, 1791590954);
