INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-148992', 148992, 'Austin Abrams', '/nvbJNwyhIICUFcS4lhxj9mGvL5z.jpg', 'Acting', '1996-09-02', 'Sarasota, Florida, USA', 'Austin Noah Abrams (born September 2, 1996) is an American actor. After making his film debut in Gangster Squad (2013), he appeared in films including The Kings of Summer (2013), Paper Towns (2015), Brad’s Status (2017), Scary Stories to Tell in the Dark (2019), Chemical Hearts (2020), Do Revenge (2022), The Starling Girl (2023), Wolfs (2024), and Weapons (2025), before starring in Resident Evil (2026). On television, he is known for his roles as Ron Anderson in The Walking Dead, Ethan Daley in Euphoria, young Marc McKeon in This Is Us, and Dash in Dash & Lily.', 'nm3641002', 1791590954, 1791590954);
