INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-84833', 84833, 'Zach Cregger', '/bpFGFfWYIrZVK7WjwkVLwIoMKEb.jpg', 'Acting', '1981-03-01', 'Arlington, Virginia, USA', 'Zachary Michael Cregger (born March 1, 1981 in Arlington, Virginia) is an American comedian, actor, writer, director and producer. He is among the founding members of the New York City-based comedy troupe The Whitest Kids U'' Know, which is composed of Trevor Moore, Sam Brown, Timmy Williams, and Darren Trumeter. He later starred in the sitcoms Friends with Benefits, Guys with Kids, and Wrecked. In 2022, Cregger wrote and directed the horror film Barbarian, a commercial success that opened to positive critical reviews. In 2025, he scored another critical and commercial hit with the horror film Weapons, which went on to win Best Supporting Actress for Amy Madigan at the 2026 Academy Awards.', 'nm1199107', 1791590954, 1791590954);
