INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1892', 1892, 'Matt Damon', '/aCvBXTAR9B1qRjIRzMBYhhbm1fR.jpg', 'Acting', '1970-10-08', 'Boston, Massachusetts, USA', 'Matthew Paige Damon (born October 8, 1970) is a multifaceted American actor, producer, and screenwriter. In 2007, he was highlighted as one of Forbes'' most bankable stars, and by 2010, he emerged as one of the highest-grossing actors in cinematic history. His accolades include an Academy Award and two Golden Globe Awards, along with nominations for three BAFTA Awards and seven Primetime Emmy Awards.

Damon''s journey in acting began with *Mystic Pizza* in 1988, but it was in 1997 that he truly came into the limelight. Collaborating with Ben Affleck on *Good Will Hunting*, they not only starred in the film but also won the Academy Award for Best Original Screenplay as well as the Golden Globe for Best Screenplay. He solidified his reputation as a leading man through iconic roles, such as Tom Ripley in *The Talented Mr. Ripley*, Jason Bourne in the *Bourne* series, and Linus Caldwell in the *Ocean''s* trilogy. His portrayal of an astronaut stranded on Mars in *The Martian* earned him a Golden Globe for Best Actor, and he has been part of various notable films, including *Saving Private Ryan*, *The Departed*, and *Ford v Ferrari*.

On the small screen, Damon played Scott Thorson in HBO''s *Behind the Candelabra*, which garnered him an Emmy nomination. His guest appearances in *30 Rock* and hosting *Saturday Night Live* were also Emmy-nominated. Beyond acting, Damon has produced projects like *Project Greenlight* and *Manchester by the Sea*. He co-founded two production companies with Ben Affleck and has lent his voice to several animated and documentary projects. His philanthropic efforts span multiple organizations, including the One Campaign and Water.org.', 'nm0000354', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-0', 'tmdb-movie-1368337', 'tmdb-person-1892', 'Odysseus', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1136406', 1136406, 'Tom Holland', '/adwEBb2sCSzqwnpVgNEG7irl1Ne.jpg', 'Acting', '1996-06-01', 'Kingston-upon-Thames, London, England', 'Thomas Stanley Holland (born 1 June 1996) is an English actor. His accolades include a BAFTA Award as well as two Critics'' Choice Awards nominations. His films as a lead actor have grossed over $9.9 billion worldwide. He was featured on the Forbes 30 Under 30 Europe list of 2019.

Holland began his career as a teen when he played a supporting role and later the title role in Billy Elliot the Musical on the West End from 2008 to 2010. He made his film debut in the disaster drama The Impossible (2012) followed by roles in the romance drama How I Live Now (2013) and the historical adventure dramas In the Heart of the Sea (2015) and The Lost City of Z (2016).

Holland achieved international recognition playing Peter Parker/Spider-Man in six Marvel Cinematic Universe (MCU) superhero films, beginning with Captain America: Civil War (2016). The following year, Holland received the BAFTA Rising Star Award and became the youngest actor to play a title role in an MCU film in Spider-Man: Homecoming. Its sequels, Far From Home (2019) and No Way Home (2021), each grossed more than $1 billion worldwide; the latter became the highest-grossing film of the year. Holland played against-type roles in the crime dramas The Devil All the Time (2020) and Cherry (2021), and starred in the big-budget films Uncharted (2022) and The Odyssey (2026).

Holland has voiced roles in the animated features Spies in Disguise (2019) and Onward (2020). On television, he took roles in the PBS historical miniseries Wolf Hall (2015) and the Apple TV+ psychological thriller limited series The Crowded Room (2023). He returned to the stage starring as one of the title roles in the West End revival of Romeo and Juliet (2024). He is married to his longtime co-star Zendaya.

Description above from the Wikipedia article Tom Holland, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm4043618', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-1', 'tmdb-movie-1368337', 'tmdb-person-1136406', 'Telemachus', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1813', 1813, 'Anne Hathaway', '/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg', 'Acting', '1982-11-12', 'Brooklyn, New York City, New York, USA', 'Anne Jacqueline Hathaway (born November 12, 1982) is an American actress. She has received numerous accolades, most notably an Academy Award for Best Supporting Actress, a Golden Globe, a BAFTA Award, and a Screen Actors Guild Award for her performance as Fantine in Les Misérables (2012). In 2015, she was one of the highest-paid actresses in the world, and in 2024, she was included on Time magazine''s list of the 100 most influential people. Additionally, she holds a Primetime Emmy Award for her voice work on The Simpsons.

​She began her career appearing in the television series Get Real (1999) before achieving worldwide fame as the lead in her film debut, the Disney comedy The Princess Diaries (2001). She earned critical acclaim for her transition to more adult roles in the dramas Havoc and Brokeback Mountain in 2005. Her star status was solidified with the commercial success of The Devil Wears Prada (2006), starring alongside Meryl Streep, and she received her first Oscar nomination for her role as a woman in rehab in Rachel Getting Married (2008).

​Since 2010, she has starred in several of her career''s biggest box-office hits, including the romantic comedies Valentine''s Day (2010) and Love and Other Drugs (2010), the fantasy film Alice in Wonderland (2010), and her role as Catwoman in The Dark Knight Rises (2012). Her films Interstellar (2014), The Intern (2015), Ocean''s 8 (2018), The Idea of You (2024), and the most recent The Odyssey (2026) have reaffirmed her versatility in the industry. Beyond her artistic work, she serves as a UN Women Goodwill Ambassador, advocating for gender equality and women''s rights in the workplace.', 'nm0004266', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-2', 'tmdb-movie-1368337', 'tmdb-person-1813', 'Penelope', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-11288', 11288, 'Robert Pattinson', '/3qZ09UE7lN6AtorfXFRYpEtSY93.jpg', 'Acting', '1986-05-13', 'Barnes, London, England, UK', 'Robert Douglas Thomas Pattinson (born May 13, 1986) is an English actor. Noted for his versatile roles in both big-budget and independent films, Pattinson has been ranked among the world''s highest-paid actors. After starting to act in a London theatre club at age 15, Pattinson began his film career by playing Cedric Diggory in the fantasy film Harry Potter and the Goblet of Fire (2005). He gained worldwide recognition for portraying Edward Cullen in The Twilight Saga film series (2008–2012), which grossed over $3.3 billion worldwide. After starring in the romantic dramas Remember Me (2010) and Water for Elephants (2011), Pattinson received critical acclaim for his performances in independent films from auteur directors. He starred in David Cronenberg''s thriller Cosmopolis (2012), David Michôd''s dystopian western The Rover (2014), James Gray''s adventure drama The Lost City of Z (2016), the Safdie Brothers'' crime drama Good Time (2017), Claire Denis'' science-fiction drama High Life (2018), and Robert Eggers'' psychological horror film The Lighthouse (2019). He returned to mainstream films with a leading role in Christopher Nolan''s spy film Tenet (2020), and starred as the DC Comics superhero Batman in Matt Reeves'' film The Batman (2022).', 'nm1500155', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-3', 'tmdb-movie-1368337', 'tmdb-person-11288', 'Antinous', 3);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1227717', 1227717, 'Himesh Patel', '/icqsXLmU0FxBGTv63kkA0GcrecO.jpg', 'Acting', '1990-10-13', 'Huntingdon, Cambridgeshire, England, UK', 'Himesh Jitendra Patel (born October 13, 1990) is a British actor. He began his career portraying Tamwar Masood in the BBC soap opera EastEnders (2007–2016). This was followed by roles in the Channel 4 sitcom Damned (2016–2018) and the films Yesterday (2019) and Tenet (2020).

In 2021, Patel starred in the HBO miniseries Station Eleven, earning a nomination for the Primetime Emmy Award for Outstanding Lead Actor in a Limited Series or Movie, and appeared in Adam McKay''s Netflix film Don''t Look Up. He then starred in the films Good Grief (2023), Greedy People (2024), The Assessment (2024) and Bubble & Squeak (2025).

Description above from the Wikipedia article Himesh Patel, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm2797744', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-4', 'tmdb-movie-1368337', 'tmdb-person-1227717', 'Eurylochus', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-6885', 6885, 'Charlize Theron', '/gd7ShD0yt4bsR2STeQ19KQ6hvXL.jpg', 'Acting', '1975-08-07', 'Benoni, Gauteng, South Africa', 'Charlize Theron (/ʃɑːrˈliːz ˈθɛrən/ shar-LEEZ THERR-ən; Afrikaans: [ʃarˈlis ˈtrɔn]; born 7 August 1975) is a South African and American actress and producer. One of the world''s highest-paid actresses, her accolades include an Academy Award and a Golden Globe Award, in addition to nominations for three BAFTAs and two Emmy Awards.

Theron came to international prominence in the 1990s by playing the leading lady in the Hollywood films The Devil''s Advocate (1997), Mighty Joe Young (1998), and The Cider House Rules (1999). She received critical acclaim for her portrayal of serial killer Aileen Wuornos in Monster (2003), for which she won the Silver Bear and Academy Award for Best Actress, becoming the first South African to win an acting Oscar. She was nominated twice more for the Oscar for portraying a sexually abused woman seeking justice in the drama North Country (2005) and Megyn Kelly in the biographical drama Bombshell (2019). She received praise for playing troubled women in Jason Reitman''s comedy-dramas Young Adult (2011) and Tully (2018).

Theron has starred in several commercially successful action films, including The Italian Job (2003), Hancock (2008), Prometheus (2012), Mad Max: Fury Road (2015), Atomic Blonde (2017), and The Old Guard (2020), as well as several Fast & Furious installments: The Fate of the Furious (2017), F9 (2021), and Fast X (2023). On television, she earned a nomination for the Primetime Emmy Award for her portrayal of Britt Ekland in the biographical film The Life and Death of Peter Sellers (2004).

Since the early 2000s, Theron has ventured into film production with her company Denver and Delilah Productions. She has produced numerous films, many in which she had a starring role, including The Burning Plain (2008), Dark Places (2015), and Long Shot (2019). Theron became an American citizen in 2007, while retaining her South African citizenship. In 2016, Time named her one of the 100 most influential people in the world.

Description above from the Wikipedia article Charlize Theron, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000234', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-5', 'tmdb-movie-1368337', 'tmdb-person-6885', 'Calypso', 5);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-5723', 5723, 'John Leguizamo', '/kwYCdxTlDh9zauUCg4mp2XTCQTw.jpg', 'Acting', '1960-07-22', 'Bogotá, Colombia', 'John Alberto Leguizamo Peláez (born July 22, 1960) is a Colombian-American stand-up comedian, actor, and film producer. He has appeared in over 100 films, produced over 20 films and documentaries, made over 30 television appearances, and has produced various television projects. He has also written and performed for the Broadway stage receiving four Tony Award nominations for Freak in 1998, Sexaholix in 2002, and Latin History for Moronsin in 2018. He received a Special Tony Award in 2018.

Leguizamo began his career as a stand-up comedian in New York City. After several years of doing supporting roles in film and television, he rose to fame with significant roles in the fantasy adventure Super Mario Bros. portraying Luigi Mario and the crime drama Carlito''s Way portraying Benny Blanco (both from 1993), followed by a role as drag queen Chi-Chi Rodriguez in the road comedy To Wong Foo, Thanks for Everything! Julie Newmar (1995), for which he received a Golden Globe Award for Best Supporting Actor nomination. Other films Leguizamo has since appeared in include Romeo + Juliet (1996), The Pest (1997), Summer of Sam (1999), Moulin Rouge! (2001), Empire (2002), Love in the Time of Cholera (2007), Righteous Kill (2008), The Lincoln Lawyer (2011), The Counselor (2013), John Wick (2014), John Wick 2 (2017), and The Menu (2022). As a voice actor, he narrated the sitcom The Brothers García (2000–2004). He played Sid the Sloth in the Ice Age franchise and Bruno Madrigal in Encanto (2021).

Leguizamo is also known for his television roles including Freak (1998) for which he received the 1999 Primetime Emmy Award for Outstanding Individual Performance in a Variety or Music Program. This historic win made Leguizamo the first Latino to win this award in Emmy history. He received further Primetime Emmy Award nominations for the miniseries Waco (2018) and the Netflix limited series When They See Us (2019). He has also appeared on ER, The Kill Point, Bloodline, and The Mandalorian. In 2023, he hosted the MSNBC series Leguizamo Does America.', 'nm0000491', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-6', 'tmdb-movie-1368337', 'tmdb-person-5723', 'Eumaeus', 6);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1978406', 1978406, 'Travis Scott', '/eBdm7HQS6lLGg4BocgfoJ5qB9yp.jpg', 'Acting', '1991-04-30', 'Houston, Texas, USA', 'Jacques Bermon Webster II (born April 30, 1991), better known by his stage name Travis Scott (formerly stylized as Travi$ Scott), is an American rapper, singer, songwriter, and record producer. His stage name is the name of a favorite uncle combined with the first name of one of his inspirations, Kid Cudi (whose real name is Scott Mescudi).

In 2012, Scott signed his first major-label contract with Epic Records and a publishing deal with Kanye West''s GOOD Music. In April 2013, he signed a joint-recording contract with Epic and T.I.''s Grand Hustle imprint. Scott''s first full-length project, the mixtape Owl Pharaoh, was self-released in 2013. It was followed by a second mixtape, Days Before Rodeo, in 2014. His debut studio album, Rodeo (2015), was led by the hit single "Antidote". His second album, Birds in the Trap Sing McKnight (2016), became his first number-one album on the Billboard 200. The following year, Scott released a collaborative album with Quavo titled Huncho Jack, Jack Huncho under the group name Huncho Jack.

In 2018, his third studio album, Astroworld, was released to critical acclaim and produced his first Billboard Hot 100 number-one single, "Sicko Mode" (featuring Drake). In late 2019, Scott''s record label Cactus Jack Records released the compilation album JackBoys, which topped the Billboard 200. After the release of his single "Franchise" (featuring Young Thug and M.I.A.) in 2020, Scott became the first artist on the Hot 100 to have three songs debut at number one in less than a year. Five years after the release of his third studio album, Scott released his highly anticipated follow-up Utopia.

Throughout his career, Scott has become a globally recognized artist and pop culture figure. Along with his highly publicized relationship with American media personality Kylie Jenner, Scott has collaborated with organizations including Nike, Dior, and McDonald''s. In 2017, he founded the record label Cactus Jack Records. Scott has also gained notoriety for controversies and legal issues regarding safety at his concerts. In November 2021, a mass-casualty crowd crush occurred during Scott''s performance at the Astroworld Festival in his hometown of Houston, Texas, resulting in widespread condemnation of the artist. Throughout his career, Scott has achieved four number-one hits on the Billboard Hot 100, along with 80 total charted songs. Additionally, he has been nominated for eight Grammy Awards and won a Billboard Music Award, Latin Grammy Award, MTV Video Music Award, and multiple BET Hip Hop Awards.', 'nm6346805', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-7', 'tmdb-movie-1368337', 'tmdb-person-1978406', 'Bard', 7);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1154054', 1154054, 'Corey Hawkins', '/wRt0Bc0chN5BSjvYzmg2evgqNzp.jpg', 'Acting', '1988-10-22', 'Arlington, Texas, USA', 'Corey Antonio Hawkins (born October 22, 1988) is an American actor. He rose to prominence for his role in the TV series The Walking Dead (2015–2016) and his portrayal of Dr. Dre in the 2015 film Straight Outta Compton, the latter of which earned him a Screen Actors Guild Award nomination. He''s also known for his performances on Broadway, starring in Six Degrees of Separation (2017) and Topdog/Underdog (2022), which earned him nominations for the Tony Award for Best Actor in a Play.

That same year, Hawkins starred in the Fox network series 24: Legacy (2017), along with Jordan Vogt-Roberts'' monster film Kong: Skull Island. In 2018, he was featured in Spike Lee''s biographical crime-comedy BlacKkKlansman, which earned him a nomination for a Screen Actors Guild Award. Hawkins received a nomination for a Primetime Emmy Award for his portrayal of Paul in the Quibi series Survive (2020).

His other roles include Michael Bay''s action-comedy 6 Underground (2019), Jon M. Chu''s musical film In the Heights (2021), and Joel Coen''s historical thriller film The Tragedy of Macbeth (2021). He starred in the 2023 film adaptation of The Color Purple.

Description above from the Wikipedia article Corey Hawkins, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm3659660', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1368337-cast-8', 'tmdb-movie-1368337', 'tmdb-person-1154054', 'Polybus', 8);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-84706', 84706, 'Jarreth J. Merz', '/ze8WDEujZmTXdCLcUy0IaymwlcS.jpg', 'Acting', '1970-05-01', 'Zurich, Switzerland', 'Jarreth J. Merz (born May 1, 1970) is a Swiss filmmaker and actor known for playing Simon of Cyrene in The Passion of the Christ (2004), as well as directing the award-winning documentary An African Election (2011).', 'nm0581711', 1791590954, 1791590954);
