INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-7401', 7401, 'Lin Shaye', '/aL87Za52elH81zMiXQn5C7AXAeg.jpg', 'Acting', '1943-10-12', 'Detroit, Michigan, USA', 'Lin Shaye (born October 12, 1943) is an American actress. In a career spanning over fifty years, Shaye has appeared in more than a hundred feature films. She is regarded as a scream queen due to her roles in various horror productions, which include the films Alone in the Dark (1982), A Nightmare on Elm Street (1984), Critters (1986) and its sequel Critters 2: The Main Course (1988), Amityville: A New Generation (1993), Wes Craven''s New Nightmare (1994), Dead End (2003), 2001 Maniacs (2005) and its sequel 2001 Maniacs: Field of Screams (2010), Ouija (2014) and its prequel Ouija: Origin of Evil (2016), Tales of Halloween (2015), Abattoir (2016), The Final Wish (2018), Room for Rent (2019), The Grudge (2019), Ted Bundy: American Boogeyman (2021), and the Insidious film series (2010–2026).

Shaye is also well known for her comedic roles in numerous films by the Farrelly brothers, including Dumb and Dumber (1994), Kingpin (1996), There''s Something About Mary (1998), Detroit Rock City (1999), Me, Myself & Irene (2000), Stuck on You (2003), and The Three Stooges (2012).

Description above from the Wikipedia article Lin Shaye, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0005417', 1791590954, 1791590954);
