INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1399526', 1399526, 'Maisie Richardson-Sellers', '/7Rue8ZtZ8uLb1x0YC9viieunoC0.jpg', 'Acting', '1992-03-02', 'London, England, UK', 'Maisie Richardson-Sellers is an English actress. She is known for her role as Amaya Jiwe / Charlie in DC''s Legends of Tomorrow series, as well as Rebekah Mikaelson / Eva Sinclair in The CW series The Originals, and also for her starring role as the daughter of King Saul of Israel, Michal, in the ABC. Bible Series Kings and Prophets. Actress best known for her starring role as Rebekah Mikaelson on The CW''s The Originals. She is also known for her portrayal of Korr Sella in the 2015 feature film Star Wars: The Force Awakens. His other credits include Legends of Tomorrow and Of Kings and Prophets.

Daughter of stage actor Joy Richardson, she grew up in England and performed in many plays during her youth. Before launching her acting career in the cinema, she obtained degrees in anthropology and archeology at the University of Oxford. She and Joseph Morgan are both known for their work in The Originals. In 2015, she entered production for the upcoming ABC series Of Kings And Prophets.', 'nm5114966', 1791590954, 1791590954);
