INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1547432', 1547432, 'Robina Beard', '/meXi83rata9p6LqRiRhqI8MPLvj.jpg', 'Acting', '1938-01-01', 'Twickenham, Middlesex, England, UK', 'Robina Beard is an English-Australian actress born in Twickenham, England in 1938. Beard has appeared in numerous stage and TV roles, but is best known for playing ''Madge'' the manicurist in the Australian and New Zealand TV advertisements for Palmolive dishwashing liquid from 1968.

Beard took dancing classes from about age 6. In 1949 Beard''s family migrated to Sydney , where she continued training in dance. Her professional career began in 1955 when she danced in the musical "Can-Can" for J. C. Williamson''s. She performed in a number of stage productions including "Alice in Wonderland" in 1959 and "The Boy Friend" in 1968.

From 1965 Beard worked on TV as a weather girl for two years before appearing as a regular on "In Melbourne Tonight" for three years as singer, dancer and choreographer. She subsequently appeared in various Australian TV series including  Barley Charlie,  No. 96, G.P., Home and Away and All Saints.

Adapted from Wikipedia and trove.gov.au', 'nm0063934', 1791590954, 1791590954);
