INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-69899', 69899, 'Zachary Levi', '/1W8L3kEMMPF9umT3ZGaNIiCYKfZ.jpg', 'Acting', '1980-09-29', 'Lake Charles, Louisiana, USA', 'Zachary Levi Pugh (/ˈzækəri ˈliːvaɪ/; born September 29, 1980) is an American actor, comedian, and singer. He received critical acclaim for starring as Chuck Bartowski in the series Chuck, and as the title character in Shazam! and its 2022 sequel, as a part of the DC Extended Universe.

He voiced Eugene Fitzherbert in the 2010 animated film Tangled, where he performed "I See the Light" with Mandy Moore; the song won a Grammy Award for Best Song Written for Visual Media. He reprised the voice role in the 2012 short film Tangled Ever After and in 2017, Rapunzel''s Tangled Adventure, a Disney Channel television series based on the film. He has appeared in the Marvel Cinematic Universe films Thor: The Dark World and Thor: Ragnarok as Fandral. Levi starred as Georg Nowack in the 2016 Broadway revival of She Loves Me opposite Laura Benanti, for which he received a Tony Award nomination.

Description above from the Wikipedia article Zachary Levi, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1157048', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1228834-cast-0', 'tmdb-movie-1228834', 'tmdb-person-69899', 'Tucker', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3896', 3896, 'Liam Neeson', '/sRLev3wJioBgun3ZoeAUFpkLy0D.jpg', 'Acting', '1952-06-07', 'Ballymena, County Antrim, Northern Ireland, UK', 'William John Neeson (born 7 June 1952) is an Irish actor. He was born in Ballymena, County Antrim, Northern Ireland and educated at Saint Patrick''s College, Ballymena Technical College and Queen''s University Belfast. He moved to Dublin after university to further his acting career, joining the renowned Abbey Theatre. In the early 1990s, he moved again to the United States, where the wide acclaim for his performance in Schindler''s List led to more high-profile work. He is widowed and lives in New York with his two sons.

He has been nominated for an Oscar, a BAFTA and three Golden Globe Awards. He has starred in a number of notable roles including Oskar Schindler in Schindler''s List, Michael Collins in Michael Collins, Peyton Westlake in Darkman, Jean Valjean in Les Misérables, Qui-Gon Jinn in Star Wars Episode I: The Phantom Menace, Alfred Kinsey in Kinsey, Ras Al Ghul in Batman Begins and the voice of Aslan in The Chronicles of Narnia film series. He has also starred in several other notable films, from major Hollywood studio releases (ie. Excalibur, The Dead Pool, Nell, Rob Roy, The Haunting, Love Actually, Kingdom of Heaven, Taken, Clash of the Titans, The A-Team, Unknown) to smaller arthouse films (ie. Deception, Breakfast on Pluto, Chloe).', 'nm0000553', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1228834-cast-1', 'tmdb-movie-1228834', 'tmdb-person-3896', 'Larry', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-51682', 51682, 'Wes Chatham', '/lFoUyX8FZs3XvUWWItCm2ezvAEs.jpg', 'Acting', '1978-10-11', 'Atlanta, Georgia, USA', 'Wes Chatham (born 11 October 1978) is an American actor best known for his roles as Amos Burton in the science fiction series The Expanse (2015–2022) and Castor in The Hunger Games film series (2014-2015).

Chatham was born in Atlanta and grew up in North Georgia. Wes''s parents divorced when he was two and he spent most of his childhood with his mother, sister, and brother. On a whim, Wes''s mother took his sister to a audition for a Tide commercial in Savannah, Georgia and brought him along. While waiting for his sister in the lobby, the casting director discovered Wes and, at the age of seven, he received his first acting job for Tide.

At the age of thirteen, Chatham moved in with his father and, without a lot of supervision and as a restless and rebellious teen, he was kicked out of high school and sent to a second chance school in Lawrenceville to finish his education. While attending classes, a professional theater company out of Atlanta started a mentoring program with the school and Chatham was chosen to write a play that was later performed by his classmates. From this experience, Chatham found his passion for the arts.

After graduating high school, Chatham joined the military as an aviation firefighter on the flight deck of the USS Essex, working in crash and salvage for four years. Chatham''s break into acting came just three months before his tour was finished when Denzel Washington chose his ship to shoot the movie Antwone Fisher. While searching for some authentic military personnel for the film, Chatham was discovered by casting director Robi Reed and given his first movie-making experience; that''s when he decided he wanted to pursue his lifelong dream of acting. Following Antwone Fisher, Reed convinced Chatham to make the move to Hollywood and shortly thereafter cast him in his first series regular role on Showtime''s Barbershop.

Chatham gained further attention acting alongside Tommy Lee Jones as Corporal Steve Penning in Paul Haggis''s In the Valley of Elah (2007) and as Frank Benedict, George W. Bush''s fraternity brother, in Oliver Stone''s biopic W. (2008). The following year, Chatham landed another series regular role on CBS'' hit TV show The Unit as Staff Sergeant Sam McBride, working with showrunners David Mamet and Shawn Ryan. Chatham also starred as Brian in the supernatural horror film Husk (2011).

In 2011, Chatham was a part of the ensemble cast of The Help, portraying Carleton Phelan, the brother of Emma Stone''s character. In 2012, the film won Outstanding Ensemble at the Screen Actors Guild Awards, and went on to receive four Academy Award nominations including Best Picture. In 2012, he landed his first title role in Joel Silver''s The Philly Kid; as a fan of mixed martial arts, Chatham dived into the character of Dillion McGwire, performing all of his own stunts. Chatham gained wider recognition for playing Castor in The Hunger Games: Mockingjay - Part 1 (2014) and Part 2 (2015), an adaptation of Suzanne Collins'' best-selling young adult dystopian novel, before landing a starring role as Amos Burton in the SyFy series The Expanse (2015-2022).', 'nm1434871', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1228834-cast-2', 'tmdb-movie-1228834', 'tmdb-person-51682', 'Alex', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-39389', 39389, 'Titus Welliver', '/3hTwn7Maktr6ONq1VvfqyRacjiv.jpg', 'Acting', '1962-03-12', 'New Haven, Connecticut, USA', 'Titus B. Welliver is an American painter, stage, television, and film actor, best recognised for his performances in the web television series ‘Bosch’ and television series ‘Sons of Anarchy’ and ‘Deadwood.’ A student of drama from the New York University, Welliver commenced his professional acting career in the early 1990s appearing in both on-screen and on-stage productions. He performed in several plays including in Shakespeare''s Henry IV Parts I and II, and ‘American Buffalo.’ His television works include playing recurring roles in series ‘NYPD Blue,’ ‘That''s Life,’ ‘Sons of Anarchy’ and ‘The Good Wife’; semi-regular role in the series ‘Deadwood’; and main role in the series ‘Brooklyn South.’ Presently he plays titular role of Detective Hieronymus "Harry" Bosch in the web television series ‘Bosch.’ His small-screen pursuits also include featuring in several television films like ‘The Day Lincoln Was Shot’; and guest starring in series such as ‘NCIS’ and ‘Law & Order.’ Notable film roles of Welliver include playing Dante Marcus in the American action thriller ‘Man on a Ledge’ and James Savoy, in the American sci-fi action film ‘Transformers: Age of Extinction.’ He has also contributed as narrator of many audio books.', 'nm0920038', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1228834-cast-3', 'tmdb-movie-1228834', 'tmdb-person-39389', 'James', 3);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-103330', 103330, 'Navid Negahban', '/pWi5tINf4mDvTYbNKZDJPODYKra.jpg', 'Acting', '1968-06-02', 'Mashhad, Iran', 'Navid Negahban is an Iranian-American actor, producer, and director whose work spans four decades, three continents, and over 166 credits in film, television, and video games.

Born in Mashhad, Iran, he discovered theater at eight years old. He left Iran in 1985, traveling through Turkey and Bulgaria before arriving at a refugee camp in Ingelheim, Germany, where he applied for asylum. He spent eight years performing with the Rheinland-Pfalz Theater in Kaiserslautern before moving to the United States in 1993. He is fluent in Persian, English, and German.

He is best known for playing Abu Nazir in Showtime''s Homeland (2011–2013), Amahl Farouk / Shadow King in FX''s Legion (2017–2019), The Sultan in Disney''s live-action Aladdin (2019), General Abdul Rashid Dostum in 12 Strong (2018), Sheikh Al-Obodi in American Sniper (2014), Faraz Hamzad in FX''s The Old Man (2022–2024), and Abbas Mansuri in Netflix''s The Night Agent (2025).

As a producer, his film Baba Joon won five Ophir Awards including Best Picture at the Israeli Film Academy. As a director, his short film The Apple Tree won Best Short Film at the Japan Indies Film Festival (2025). He received a BAFTA Games Award nomination for Best Performer for his work on 1979 Revolution: Black Friday (2017).

He is represented by Innovative Artists. Official website: https://navidnegahban.com', 'nm1041023', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1228834-cast-4', 'tmdb-movie-1228834', 'tmdb-person-103330', 'Qasim', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1257563', 1257563, 'Annet Mahendru', '/kEeokLN5vJsOdKSEFaN36qlzCRa.jpg', 'Acting', '1989-08-21', 'Kabul, Afghanistan', 'Annet Mahendru (born August 21, 1989) is an actress best known for her starring role as Nina Sergeevna Krilova in the 2013 FX series, The Americans. She is also known for her role as Jennifer "Huck" Mallick in the 2020 AMC series, The Walking Dead: World Beyond.

Mahendru was born to a Russian mother and Hindu Indian father in Afghanistan. She had what she calls a "gypsy" childhood, spending her first seven years of her childhood between Afghanistan and Saint Petersburg. She then lived with her mother at Saint Petersburg and regularly travelled between there and Frankfurt, before moving with her father to East Meadow, New York, at age 13, after her parents separated.

Mahendru is married to Australian filmmaker Louie Gibson. The couple have a son (born c. 2018). In addition to English, she is fluent in German, Russian, and Persian, and also speaks conversational French and Hindi.', 'nm3393732', 1791590954, 1791590954);
