INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2114526', 2114526, 'Elnaaz Norouzi', '/gbiXh5zoIKFH1kEPFtuhjfElY5c.jpg', 'Acting', '1992-07-09', 'Tehran, Iran', 'Elnaaz Norouzi is an Iranian actress and model who has appeared in films and television. She plays Zoya in Netflix India''s first original show Sacred Games. She has also appeared with Guru Randhawa in his music video for his Made in India. She made her film debut with 2018 movie Khido Khundi .', 'nm9157672', 1791590954, 1791590954);
