INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-movie-1228834-rev-0', 'tmdb-movie-1228834', 'Sierbahnn', 6, 'This is gritty and convoluted just like a heist movie should be. Zachary doesn''t do a very good job in it, and Liam is in it far too little. The hang-up of the group trying to atone for past mistakes becomes almost like exposition. It doesn''t quite land, and therefore the ending doesn''t feel very earned. I still enjoyed the movie, but it isn''t a particularly good version of a heist like this.', '2026-09-25T08:24:36Z');
