INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-64295', 64295, 'Alan Ritchson', '/92YNEEpCyugkTzPprJwZpvVtvuK.jpg', 'Acting', '1982-11-28', 'Grand Forks, North Dakota, USA', 'Alan Michael Ritchson (born November 28, 1982) is an American actor. He made his acting debut as Aquaman / Arthur Curry on The CW superhero series Smallville (2005–10), where he appeared as a guest star between the fifth and 10th seasons. He subsequently had a starring role in the Spike TV sitcom Blue Mountain State (2010–2012), a role he reprised in the 2016 film sequel. He also headlined the SyFy action series Blood Drive (2017), and returned to superhero television as Hank Hall / Hawk on the DC Universe / HBO Max series Titans from 2018 to 2021. He gained wider recognition for portraying the title character in the ongoing Amazon Prime Video action thriller series Reacher since 2022.

Outside television, Ritchson played Raphael in the 2014 Teenage Mutant Ninja Turtles reboot and its 2016 sequel, along with appearances in The Hunger Games: Catching Fire (2013), Lazer Team (2015), and Fast X (2023). He made his directorial debut and co-starred in the action-comedy Dark Web: Cicada 3301 (2021).

Description above from the Wikipedia article Alan Ritchson, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm2024927', 1791590954, 1791590954);
