INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-17289', 17289, 'Rodrigo Santoro', '/d3MaF9SPHDn2PMYHuqdnO0Csik6.jpg', 'Acting', '1975-08-22', 'Petrópolis, Rio de Janeiro, Brazil', 'Rodrigo Junqueira dos Reis Santoro (Petrópolis, August 22, 1975) is a Brazilian actor and voice actor. He has appeared in many successful movies, including Brainstorm (2001), Carandiru (2003), 300 (2007), Che (2008), I Love You Phillip Morris (2009) and Rio (2011). He was also a series regular on the Television series Lost portraying the character Paulo.', 'nm0763928', 1791590954, 1791590954);
