INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1331024', 1331024, 'Kate Box', '/zv4NckgNBn6Tc2xhCdNFFx9o9EZ.jpg', 'Acting', '1979-08-25', 'Adelaide, South Australia, Australia', 'Kate Box is an Australian stage, film and television actress, Box was born in Adelaide, South Australia. She is known for her roles as Nicole Vergas in Rake (2010) and as Lou Kelly in Wentworth (2013).', 'nm2094547', 1791590954, 1791590954);
