INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-220914', 220914, 'Peta Sergeant', '/owkSN29t7P6hpazZKsUMt7FybrP.jpg', 'Acting', '1980-01-01', 'Penang, Malaysia', 'Peta Sergeant is an Australian-Malaysian actress. Born in 1981 in Malaysia and raised in Brisbane, Australia. While in high school, she had dreams of being a marine biologist, but a hobby for drama acting prompted her to audition and receive acceptance at the National Institute of Dramatic Art. She graduated in 2000 at twenty years old. Despite landing television roles and even producing a play fresh out of drama school, Peta decided to abandon the industry and travel overseas for eighteen months, which helped her gain a commitment to acting. Her notable television credits include British science-fiction and drama series Jeopardy, Headland, and numerous Australian drama series such as Last Man Standing, All Saints, Canal Road and Satisfaction. She starred in the films Iron Sky and Crawlspace. In 2020 Sergeant portrayed Terisa Kerrill in the Star Wars: Squadrons video game. In 2021, she joined the cast of Supergirl, as the magical imp Nyxlygsptlnz/Nyxly, a fifth Dimensional imp like Mr Mxyzptlk (who was played by fellow Once Upon a Time actor, Peter Gadiot, before being replaced by The Odd Couple actor, Thomas Lennon).', 'nm1560632', 1791590954, 1791590954);
