INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1290158', 1290158, 'James Crompton', '/o9ByykxXcYjHGg60hB07zi8MYtL.jpg', 'Acting', NULL, NULL, 'James Crompton is an actor, writer and musician. He recently appeared as Morrie in "3 Mile Limit", The Radio Hauraki story, which has been nominated in twenty international festivals, and won awards in seven of those. Prior to that he appeared in WW2 drama, "Journey Of A Story" as theatre director Lawrence Burton. His Pythonesque self-penned short film "The Psychologist" has been accepted into festivals worldwide. He has many theatre credits including many Shakespeare productions, and has played the iconic David Attenborough in the acclaimed theatre production "Birds Of Paradise". He moonlights as a singer/songwriter and has released an album entitled "The Karmic Loo" under the name Crompy available on most digital outlets. He has also released a poetry book series, titles include: ''The Leaves Of Autumn'', ''In the Dead Of Winter'', ''The Birth of Spring'' and ''In The Heat Of Summer''. He is a distant relative of Ian Fleming, the writer of James Bond. Bio by James Crompton', 'nm0188644', 1791590954, 1791590954);
