INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-movie-1751701-rev-0', 'tmdb-movie-1751701', 'Sierbahnn', 5, 'Isolation is difficult to commit to film because without dialogue the action can sometimes feel like it''s dragging. This movie suffers from this during its first half and once it obtains enough characters to actually hold conversations, it turns out that they are somewhat dull and that the characters are difficult to engage with. Your point of view is very set and it''s difficult to engage with any of the other characters. Overall I felt that this was an overly slow depiction of a poorly realized end of the world. For instance, an impact like this would have made the air unbreathable but everyone seems to be doing just fine and that breaks the immersion of the story being told.', '2026-09-18T08:20:10Z');
