INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-521673', 521673, 'Sahajak Boonthanakit', '/a36MI02S0f11bJZjBoxkZTsUDAK.jpg', 'Acting', NULL, 'Bangkok, Thailand', 'Born in Bangkok, Thailand, lived in Nairobi, Kenya 10+ yrs and New York 20+ yrs. Started acting in Nairobi (stage) for 4 yrs. Returning to Thailand where in 1999 he landed his first movie role in The Beach (1999) with Leonardo DiCaprio, followed by Broke Down Palace (1999) with Claire Danes. He has since been in over 80 productions including, Only God Forgives (2013) with Ryan Gosling and Kristen Scott Thomas, The Lady (2011) with Michelle Yeoh and David Thewlis, No Escape (2015) with Pierce Brosnan and Owen Wilson.', 'nm0095465', 1791590954, 1791590954);
