INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-62831', 62831, 'Will Forte', '/4VEzbkL3HwHTUZAPA5PyypFG2U.jpg', 'Acting', '1970-06-17', 'Alameda, California, USA', 'Orville Willis Forte IV (/ˈfɔːrteɪ/ FOR-tay; born June 17, 1970) is an American actor, comedian, writer, and producer. He was a cast member and writer on the NBC sketch comedy series Saturday Night Live for eight seasons from 2002 to 2010. During his time on the show, he played a recurring character that led to a feature film adaptation, MacGruber (2010), and a streaming limited series in 2021. Forte also created and starred in the sitcom The Last Man on Earth (2015–2018). He received three Primetime Emmy Award nominations for the series: two for acting and one for writing.

After obtaining a history degree from the University of California, Los Angeles and becoming a financial broker like his father, Forte changed his career path to comedy and took classes with the improv group The Groundlings. Before joining Saturday Night Live, he worked as a writer and producer on 3rd Rock from the Sun and That ''70s Show. Forte played various roles in comedy before starring in the drama film Nebraska (2013). He has provided voice work for the Cloudy with a Chance of Meatballs films (2009–2013), My Life as a Courgette, Get Squirrely (2016), Luis & the Aliens (2018), The Willoughbys and Scoob! (2020), also voicing Eddy in Disney XD''s Lab Rats, and Abraham Lincoln in Clone High (2002–2003, 2023–2024), The Lego Movie films (2014–2019), Michelangelo and Lincoln: History Cops (2014), America: The Motion Picture (2021), Scott Pilgrim Takes Off (2023) and Sausage Party: Foodtopia (2024–present).

Description above from the Wikipedia article Will Forte, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0287182', 1791590954, 1791590954);
