INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1452046', 1452046, 'Lana Condor', '/vWn27Fk2GLwH7o9fBG9hBWZI6OR.jpg', 'Acting', '1997-05-11', 'Cần Thơ, Vietnam', 'Lana Therese Condor (born Trần Đồng Lan; May 11, 1997) is an American actress and YouTuber. She made her acting debut starring as Jubilee in the superhero film X-Men: Apocalypse (2016). She gained international recognition for portraying Lara Jean Covey in the romantic comedy To All the Boys film series (2018–2021). She has also portrayed Saya Kuroki in the television series Deadly Class (2019) and Koyomi in Alita: Battle Angel (2019). More recently, Condor voiced the titular character in the animated teen comedy film Ruby Gillman, Teenage Kraken (2023).

Description above from the Wikipedia article Lana Condor, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm7093076', 1791590954, 1791590954);
