INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-40481', 40481, 'Luis Guzmán', '/kSdxUckOJj9R5VKrLUnRy14YhNV.jpg', 'Acting', '1956-08-28', 'Cayey, Puerto Rico', 'Luis Guzmán (born August 28, 1956) is a Puerto Rico-American actor. He is known for his character work. For much of his career, his squat build, wolfish features, and brooding countenance have garnered him roles largely as sidekicks, thugs, or policemen, but his later career has seen him move into more mainstream roles. He is a favorite of director Steven Soderbergh, who cast him in Out of Sight, The Limey, and Traffic, and Paul Thomas Anderson, who cast him in Boogie Nights, Magnolia and Punch-Drunk Love. He also voiced Ricardo Diaz in Grand Theft Auto: Vice City and Grand Theft Auto: Vice City Stories.', 'nm0350079', 1791590954, 1791590954);
