INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-41561', 41561, 'Kenneth Choi', '/3606Uo4fiUtV9Y6eOwpM48qpSgJ.jpg', 'Acting', '1971-10-20', 'Chicago, Illinois, USA', 'Kenneth Choi (born October 20, 1971) is an American actor. He is known for playing Henry Lin on the television series Sons of Anarchy (2008–2014), Chester Ming in Martin Scorsese''s The Wolf of Wall Street (2013), and Judge Lance Ito in The People v. O. J. Simpson: American Crime Story (2016). He is also known for his roles as Jim Morita and Principal Morita in the Marvel Cinematic Universe films Captain America: The First Avenger (2011) and Spider-Man: Homecoming (2017), respectively, and Lewis on the Fox comedy series The Last Man on Earth (2016–2017). Since 2018, he has starred in the Fox drama series 9-1-1, playing LAFD firefighter Howie "Chimney" Han.

