INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-115150', 115150, 'Kaya Scodelario', '/qmtXUabwXw0RvyK6R0la6CmvGxr.jpg', 'Acting', '1992-03-13', 'Haywards Heath, West Sussex, London, England, UK', 'Kaya Rose Scodelario-Davis (née Humphrey; born 13 March 1992) is an English actress best known for her roles as Effy Stonem on the E4 teen drama Skins (2007–2010, 2013), and Teresa in the Maze Runner film series (2014–2018). Other roles include Catherine Earnshaw in Andrea Arnold''s Wuthering Heights (2011), Carina Smyth in Pirates of the Caribbean: Dead Men Tell No Tales (2017), Carole Ann Boone in Extremely Wicked, Shockingly Evil and Vile (2019), Haley Keller in Crawl (2019), Katarina Baker in the Netflix original series Spinning Out (2020) and Claire Redfield in Resident Evil: Welcome to Raccoon City (2021).', 'nm2546012', 1791590954, 1791590954);
