INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1408809', 1408809, 'Hannah John-Kamen', '/2fqNQQW3B7upH4rBubhxXkIIoGk.jpg', 'Acting', '1989-09-07', 'Anlaby, East Yorkshire, England, UK', 'Hannah Dominique John-Kamen (born 7 September 1989) is an English actress. She is known for her television roles in Black Mirror (2011–2016), Killjoys (2015–2019), Brave New World (2020), and the Netflix miniseries The Stranger (2020). She has portrayed  Ava Starr / Ghost in the superhero films Ant-Man and the Wasp (2018), Thunderbolts* (2025) and Avengers: Doomsday (2026). She has also starred in various films, including SAS: Red Notice (2021), Resident Evil: Welcome to Raccoon City (2021) and Unwelcome (2023).

Description above from the Wikipedia article Hannah John-Kamen, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm4789912', 1791590954, 1791590954);
