INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1223726', 1223726, 'Robbie Amell', '/5MPx1TEdgPs9UEXV65nd80JikSH.jpg', 'Acting', '1988-04-21', 'Toronto, Ontario, Canada', 'Robert Patrick Amell IV (born April 21, 1988) is a Canadian-American actor and producer. He is best known for his roles as Stephen Jameson on The CW series The Tomorrow People (2013–2014), Ronnie Raymond / Firestorm on The CW series The Flash (2014–2017, 2022), and Nathan Brown in the Prime Video series Upload (2020–). Other roles include Fred Jones in the films Scooby-Doo! The Mystery Begins (2009) and Scooby-Doo! Curse of the Lake Monster (2010), The Hunters as Paxton Flynn (2013), The DUFF as Wesley Rush (2015), The Babysitter as Max (2017), and the science fiction film Code 8 as Connor Reed (2019); the latter of which also starred his cousin, Stephen Amell. He also appeared on television shows such as Life with Derek (2006–2008), True Jackson, VP (2008–2011), Unnatural History (2010), and Revenge (2011–2012).

Description above from the Wikipedia article Robbie Amell, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm2064412', 1791590954, 1791590954);
