INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-10825', 10825, 'Donal Logue', '/5Rj850yVkIqsgCihtZLbkNSHbFb.jpg', 'Acting', '1966-02-27', 'Ottawa, Ontario, Canada', 'Donal Francis Logue (born February 27, 1966) is an Canadian actor, producer and writer. His notable roles include starring as Dex in The Tao of Steve, Father Brian Norris in Runaway Bride, Quinn in Blade, Dan Scott in The Patriot, Jack in Just Like Heaven, Alex Balder in Max Payne, and Mack in Ghost Rider.

His major roles on TV include starring as Detective Harvey Bullock on Fox''s Gotham, Declan Murphy on NBC''s Law & Order: SVU, Sean Finnerty on the sitcom Grounded for Life, ADA Dickie Flood on The Practice, Chuck Martin on ER, Capt. Kevin Tidwell on Life, Hank Dolworth on Terriers, Brendan Donovan on Copper, Lee Toric on Sons of Anarchy, King Horik on Vikings, Dan on Quibi''s series Dummy, Sheriff McCullough on Departure, Ken Schuler on Public Morals, Eugene Gurkin on The Knights of Prosperity, and Dr. Danny Macklin on Medicine Ball.', 'nm0006610', 1791590954, 1791590954);
