INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2203', 2203, 'Neal McDonough', '/3mI3i1CpjATSCta1Tb2qsyl1KCh.jpg', 'Acting', '1966-02-13', 'Dorchester, Massachusetts, USA', 'Neal McDonough was trained at the London Academy of Dramatic Arts and Sciences. His theatre credits include ''Cheap Talk'', ''Foreigner'', ''As You Like It'', ''Rivals'', ''A Midsummer Night''s Dream'', ''Bald Soprano'', and ''Waiting for Lefty''. The young actor won a 1991 Best Actor Dramalogue Award for ''Away Alone''. McDonough has been a ''Star Trek'' fan since he was a kid. Playing Lieutenant Hawk in ''Star Trek First Contact'' was a life-long dream. McDonough has three pictures on his bedroom wall. One is a picture of his mom, the other is the Holy Virgin Mary, and the third is William Shatner as Captain Kirk. He has numerous television credits including ''NYPD Blue'', ''Quantum Leap'', and the voice of Bruce Banner in the animated series ''The Incredible Hulk'' among others. He graduated Syracuse University with a Bachelor of Fine Arts degree in 1988. ', 'nm0568180', 1791590954, 1791590954);
