INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1813', 1813, 'Anne Hathaway', '/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg', 'Acting', '1982-11-12', 'Brooklyn, New York City, New York, USA', 'Anne Jacqueline Hathaway (born November 12, 1982) is an American actress. She has received numerous accolades, most notably an Academy Award for Best Supporting Actress, a Golden Globe, a BAFTA Award, and a Screen Actors Guild Award for her performance as Fantine in Les Misérables (2012). In 2015, she was one of the highest-paid actresses in the world, and in 2024, she was included on Time magazine''s list of the 100 most influential people. Additionally, she holds a Primetime Emmy Award for her voice work on The Simpsons.

​She began her career appearing in the television series Get Real (1999) before achieving worldwide fame as the lead in her film debut, the Disney comedy The Princess Diaries (2001). She earned critical acclaim for her transition to more adult roles in the dramas Havoc and Brokeback Mountain in 2005. Her star status was solidified with the commercial success of The Devil Wears Prada (2006), starring alongside Meryl Streep, and she received her first Oscar nomination for her role as a woman in rehab in Rachel Getting Married (2008).

​Since 2010, she has starred in several of her career''s biggest box-office hits, including the romantic comedies Valentine''s Day (2010) and Love and Other Drugs (2010), the fantasy film Alice in Wonderland (2010), and her role as Catwoman in The Dark Knight Rises (2012). Her films Interstellar (2014), The Intern (2015), Ocean''s 8 (2018), The Idea of You (2024), and the most recent The Odyssey (2026) have reaffirmed her versatility in the industry. Beyond her artistic work, she serves as a UN Women Goodwill Ambassador, advocating for gender equality and women''s rights in the workplace.', 'nm0004266', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1101383-cast-0', 'tmdb-movie-1101383', 'tmdb-person-1813', 'Denise Platt', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3061', 3061, 'Ewan McGregor', '/q2UDxfwWnmXTB7khOUF3J9puBVP.jpg', 'Acting', '1971-03-31', 'Perth, Scotland, UK', 'Ewan Gordon McGregor (born March 31, 1971) is a Scottish actor. His accolades include a Golden Globe Award and a Primetime Emmy Award. In 2013, he was appointed Officer of the Order of the British Empire (OBE) for his services to drama and charity.

While studying drama at the Guildhall School of Music and Drama, McGregor began his career with a leading role in the British series Lipstick on Your Collar (1993). He gained international recognition for starring as drug addict Mark Renton in Trainspotting (1996) and as Obi-Wan Kenobi in the Star Wars prequel trilogy (1999–2005). His career progressed with starring roles in the musical Moulin Rouge! (2001), action film Black Hawk Down (2001), fantasy film Big Fish (2003), and thriller Angels and Demons (2009). He gained praise for his performances in the thriller The Ghost Writer (2010) and romantic comedy Salmon Fishing in the Yemen (2011).

McGregor made his directorial debut with the crime film American Pastoral (2016), in which he also starred. For his dual role as brothers Ray and Emmit Stussy in the third season of the anthology series Fargo (2017), he won the Golden Globe Award for Best Actor – Miniseries or Television Film. He voiced Lumière in Beauty and the Beast (2017), and played the title role in Christopher Robin (2018), Dan Torrance in Doctor Sleep (2019), and Black Mask in Birds of Prey (2020). He reprised his role as Kenobi in the 2022 miniseries Obi-Wan Kenobi, and won a Primetime Emmy Award for Outstanding Lead Actor for his portrayal of fashion designer Halston in the miniseries Halston (2021).

McGregor has also starred in theatre productions of Guys and Dolls (2005–2007) and Othello (2007–2008). He has been involved in charity work and has served as an ambassador for UNICEF UK since 2004.', 'nm0000191', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1101383-cast-1', 'tmdb-movie-1101383', 'tmdb-person-3061', 'Greg Platt', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1104567', 1104567, 'Maisy Stella', '/dlnP0Yzbr9EEbVg6M0PQVQ7pwUF.jpg', 'Acting', '2003-12-13', 'Oshawa, Ontario, Canada', 'Maisy Stella (born December 13, 2003) is a Canadian singer and actress. Her accolades include a Critics'' Choice Movie Award and an Independent Spirit Award.

Stella started her career in 2009 and gained early attention as half of the country music cover band Lennon & Maisy, alongside her elder sister Lennon. From 2012 to 2018, they starred together as sisters on the musical television series Nashville, for which they also contributed to the soundtrack discography.

In 2017, Stella released her debut solo song, "Riding Free", for the soundtrack of the animated series Spirit Riding Free. In 2024, she returned to acting and received greater recognition for her leading role in Megan Park''s coming-of-age film My Old Ass (2024), for which she won the Critics'' Choice Movie Award for Best Young Performer. She has since acted in Maude Apatow''s comedy drama Poetic License (2025).

Description above from the Wikipedia article Maisy Stella, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm5204873', 1791590954, 1791590954);
