INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1900828', 1900828, 'Jordan Alexa Davis', '/itz31u3sG9hAlwuFZ6FWz1KhY1R.jpg', 'Acting', '2003-07-08', 'Los Angeles, California, USA', 'Jordan Alexa Davis (born July 8, 2003) is an American actress. Her theater work includes performances in productions of Hairspray the Musical and Shrek the Musical. She came to spotlight on screen as Sarah Grohl in the Apple TV miniseries Defending Jacob (2020). Her first role in a feature film was in The End of Oak Street (2026).', 'nm6506457', 1791590954, 1791590954);
