INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-156395', 156395, 'Anne Gee Byrd', '/yNqUNepmVQ462yoTnZOWVbudKeG.jpg', 'Acting', '1938-01-05', 'Toledo, Ohio, USA', 'Anne Gee Byrd (January 5, 1938, in Toledo, Ohio) is an American actress. She began her career in theater and appeared in numerous stage productions before transitioning to television and film. Byrd has acted in series such as Little House on the Prairie, Remington Steele, ER, Monk, and Law & Order: LA. On the big screen, she was seen in Moving (1988), 8mm (1999), and Wild (2014). In addition to her acting career, she was recognized for her work in theater and won several Los Angeles Drama Critics Circle Awards. She was married to actor David Byrd and has a daughter. Byrd lives in Los Angeles and remains active in film, television, and theater', 'nm0125988', 1791590954, 1791590954);
