INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-156511', 156511, 'Emily Kuroda', '/yaZhAxSsElEaX0az2U6FUBN38ET.jpg', 'Acting', '1952-10-30', 'Fresno, California, USA', 'Emily Keiko Kuroda (born October 30, 1952) is an American actress. She is best known for her role as Mrs. Kim on TV''s Gilmore Girls, but she has had a long career on stage and screen and is a veteran of East West Players, Los Angeles''s premier Asian American theater group.', 'nm0475836', 1791590954, 1791590954);
