INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1935905', 1935905, 'Grayson Thorne Kilpatrick', '/17xq5SJh6GTr9a2nRmDhxH3TUZ7.jpg', 'Acting', '2004-04-01', 'Huntsville, Alabama, USA', 'Grayson Thorne Kilpatrick was born in Huntsville, AL to Sherry and Charles Kilpatrick. In 2013, at the age of 9 he fell in love with Acting. Grayson took some local acting classes at Hollywood Huntsville in Huntsville, AL and Gray Studio in Nashville, TN in 2013 Grayson made his screen debut with Tom Lester, Victoria Jackson and Ray Stevens in "Campin'' Buddies". From 2013 until end of 2015 Grayson had received 24 IMDb credit for Feature Films, Short Films and TV Series. In 2016, Grayson and his family moved to Los Angeles where Grayson has already received several more IMDb credit for various TV Series and Films. Grayson joined the Screen Actors Guild and became SAG-AFTRA in February 2016, only one month after moving to L.A. Grayson has worked with legendary actors Shia LeBeouf, Will Ferrell, Mark Wahlberg, Bill Hader, Fred Armisen, Jamie Costa, Stephen Dorff, Rob Riggle, Alpha Trivette, Greg Alan Williams, Danny Vinson and Henry Zebrowski.

Grayson is known for his roles in Chicken Girls:The Movie, American Horror Story, Dave and many more

Grayson currently takes acting Classes from David Gray at Gray Studios in L.A as well as the Margie Haber Studios. Grayson takes private acting classes with Wendy Ann Faraone an on set Disney acting coach for shows as "Liv and Maddie", Carrie Ann Hunt actress from "Magic Mike" and Danny Vinson actor from such films as "Walk the Line", "The Curious Case of Benjamin Button" and many more...

Grayson is currently pursing his Black Belt in Karate, and taking Surfing, and Parkour lessons. His hobbies is playing Minecraft with his friends, Archery and watching College Football (Alabama Crimson Tide).', 'nm6345366', 1791590954, 1791590954);
