INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-500', 500, 'Tom Cruise', '/maf8PhSvDCdEwjEMbYfGpojR5RP.jpg', 'Acting', '1962-07-03', 'Syracuse, New York, USA', 'Thomas Cruise Mapother IV (/ˈmeɪˌpɒθər/ MAY-poth-ər; born July 3, 1962) is an American actor and film producer. Regarded as a Hollywood icon, he has received various accolades, including an Honorary Palme d''Or, an Academy Honorary Award, and three Golden Globes, in addition to nominations for four competitive Academy Awards. As of 2026, his films have grossed more than $13.3 billion worldwide, placing him among the highest-grossing actors of all time. One of Hollywood''s most bankable stars, he is consistently one of the world''s highest-paid actors.

Cruise began acting in the early 1980s and made his breakthrough with leading roles in Risky Business (1983) and Top Gun (1986), the latter earning him a reputation as a sex symbol. Critical acclaim came with his roles in the dramas The Color of Money (1986), Rain Man (1988), and Born on the Fourth of July (1989). For his portrayal of Ron Kovic in the latter, he won a Golden Globe Award and received a nomination for the Academy Award for Best Actor. As a leading Hollywood star in the 1990s, he starred in commercially successful films, including the drama A Few Good Men (1992), the thriller The Firm (1993), the horror film Interview with the Vampire (1994), and the sports comedy-drama Jerry Maguire (1996); for the latter, he won a Golden Globe Award for Best Actor and his second nomination for the Academy Award for Best Actor. Cruise''s performance in the drama Magnolia (1999) earned him another Golden Globe Award and a nomination for the Academy Award for Best Supporting Actor.

Cruise subsequently established himself as a star of science fiction and action films, often performing his own risky stunts. He played fictional agent Ethan Hunt in the Mission: Impossible film series (1996–2025). His other films in the genre include Vanilla Sky (2001), Minority Report (2002), The Last Samurai (2003), Collateral (2004), War of the Worlds (2005), Knight and Day (2010), Jack Reacher (2012), Oblivion (2013), Edge of Tomorrow (2014), and Top Gun: Maverick (2022).

Cruise holds the Guinness World Record for the most consecutive $100 million-grossing movies, a feat achieved with eleven films released between 2012 and 2025. In December 2024, he was awarded the U.S. Navy''s highest civilian honor, the Distinguished Public Service Award, in recognition of his "outstanding contributions" to the military, with his screen roles. In March 2025, he was named the recipient of the British Film Institute Fellowship, the BFI''s highest honor, for his contributions to cinema. Forbes ranked him as the world''s most powerful celebrity in 2006. He was named People''s Sexiest Man Alive in 1990, and received the top honor of "Most Beautiful People" in 1997. Outside his film career, Cruise has been an outspoken advocate for the Church of Scientology, which has resulted in controversy and scrutiny of his involvement in the organization. An aviation enthusiast, he has held a pilot certificate since 1994.

Description above from the Wikipedia Tom Cruise, article licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000129', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1248832-cast-0', 'tmdb-movie-1248832', 'tmdb-person-500', 'Digger Rockwell', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-53240', 53240, 'Riz Ahmed', '/1uP9RaX7BGVx7XGTEmwObBJJzsC.jpg', 'Acting', '1982-12-01', 'Wembley, London, England, UK', 'Rizwan Ahmed (born 1 December 1982) is a British actor and rapper. He has received several awards, including an Academy Award and a Primetime Emmy Award, and nominations for two Golden Globe Awards and two British Academy Film Awards. In 2017, he was named by Time as one of the most influential people in the world. He also created the TV series Englistan in 2018 for the BBC, which was also his writing debut.

After studying acting at the Royal Central School of Speech and Drama, Ahmed began his acting career with independent films such as The Road to Guantanamo (2006), Shifty (2008), Four Lions (2010), Trishna (2011), and The Reluctant Fundamentalist (2012). He had his break-out role in Nightcrawler (2014), which led to roles in the 2016 big-budget films Jason Bourne and Rogue One. For starring as a young man accused of murder in the HBO miniseries The Night Of (2016), Ahmed won the Primetime Emmy Award for Outstanding Lead Actor in a Limited Series. He received another Emmy nomination in the same year for his guest role in Girls. He went on to play Carlton Drake in the superhero film Venom (2018) and a drummer who loses his hearing in the drama film Sound of Metal (2019). The latter earned him a nomination for the Academy Award for Best Actor. He produced, co-wrote, and starred in Mogul Mowgli (2020), which earned a nomination for the BAFTA Award for Outstanding British Film.

As a rapper, Ahmed is a member of the Swet Shop Boys, and has earned critical acclaim with the hip-hop albums Microscope and Cashmere, and commercial success featuring in the Billboard 200 chart-topping Hamilton Mixtape, with his song "Immigrants (We Get the Job Done)" winning an MTV Video Music Award. His second studio album, The Long Goodbye, was accompanied by a short film of the same name, which won him the Academy Award for Best Live Action Short Film.

Description above from the Wikipedia article Riz Ahmed, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1981893', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1248832-cast-1', 'tmdb-movie-1248832', 'tmdb-person-53240', 'Nirav Ganesh', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1230', 1230, 'John Goodman', '/yyYqoyKHO7hE1zpgEV2XlqYWcNV.jpg', 'Acting', '1952-06-20', 'Saint Louis, Missouri, USA', 'John Stephen Goodman (born June 20, 1952) is an American actor. He rose to prominence in television before becoming an acclaimed and popular film actor. Goodman has received various accolades, including a Primetime Emmy Award, a Golden Globe Award, and a Screen Actors Guild Award. Vanity Fair has called him "among our very finest actors".

Goodman is known for his collaborations with the Coen brothers, appearing in films such as Raising Arizona (1987), Barton Fink (1991), The Big Lebowski (1998), and O Brother, Where Art Thou? (2000), and Inside Llewyn Davis (2013). He took leading roles in King Ralph (1991), The Babe (1992), Matinee (1993), The Flintstones (1994), and 10 Cloverfield Lane (2016) as well as supporting roles in Revenge of the Nerds (1984), True Stories (1986),  Bringing Out the Dead (1999), Evan Almighty (2007), Speed Racer (2008), The Artist (2011), Flight (2012), Argo (2012), and Atomic Blonde (2017). He voiced roles in The Emperor''s New Groove franchise (2000–2008), the Monsters, Inc. franchise (2001–present), Bee Movie (2007) and Smurfs (2025).

On television, Goodman gained recognition playing the family patriarch Dan Conner in the ABC comedy series Roseanne (1988–1997; 2018), and The Conners (2018–2025). Goodman has played an English professor in the drama series Treme (2010–2011), a military contractor in the legal drama series Damages (2011), a Republican senator in the political satire Alpha House (2013–2014), and a televangelist in the comedy series The Righteous Gemstones (2019–2025). He also guest-starred in The West Wing (2003–2004), Studio 60 on the Sunset Strip (2006), and Community (2011–2012), and is a member of the Five Timers Club, having hosted Saturday Night Live 13 times from 1989 to 2013. 

Goodman started his career at The Public Theatre acting in numerous productions including Henry IV, Part 1 (1981), The Skin of Our Teeth (1998), and The Seagull (2001). He made his Broadway debut in Big River (1985), for which Goodman received a Drama Desk Award for Outstanding Featured Actor in a Musical nomination. He returned to Broadway in revivals of the Samuel Beckett play Waiting for Godot (2009), and the newspaper comedy The Front Page (2016). Goodman made his West End debut in a revival of David Mamet''s American Buffalo (2015).

Description above from the Wikipedia article John Goodman, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000422', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1248832-cast-2', 'tmdb-movie-1248832', 'tmdb-person-1230', 'President Compson', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-7152', 7152, 'Sandra Hüller', '/jQfKXVCPTH9KEnzHHU4QemCnlMe.jpg', 'Acting', '1978-04-30', 'Suhl, Germany', 'Sandra Hüller (German: [ˈzandʁa ˈhʏlɐ]; born 30 April 1978) is a German actress. She has received various accolades, including two Silver Bears and a César Award, along with nominations for an Academy Award, two BAFTAs, and a Golden Globe Award.

Hüller made her film debut in 1999. She would go on to win Silver Bear for Best Actress for her performance as a woman based on the case of Anneliese Michel in Hans-Christian Schmid''s drama Requiem (2006) and the Silver Bear for Best Leading Performance for playing a female soldier disguised as a man in Markus Schleinzer''s drama Rose (2026). She also took leading roles in Maren Ade''s comedy Toni Erdmann (2016) and Frauke Finsterwalder''s historical black comedy Sisi & I (2023). 

She gained international recognition in 2023 for her starring roles in Justine Triet''s legal drama Anatomy of a Fall and Jonathan Glazer''s Holocaust drama The Zone of Interest. Her performance in the former won a César Award and earned her an Academy Award nomination for Best Actress. In 2026, she appeared in the science-fiction comedy-drama Project Hail Mary, the Paweł Pawlikowski drama Fatherland, and the Alejandro G. Iñárritu satire Digger.

Description above from the Wikipedia article Sandra Hüller, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1197689', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1248832-cast-3', 'tmdb-movie-1248832', 'tmdb-person-7152', 'Emma', 3);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-72873', 72873, 'Michael Stuhlbarg', '/aYB3SQm3h6ZyAdlbGyiNfakjx56.jpg', 'Acting', '1968-07-05', 'Long Beach, California, USA', 'Michael Stuhlbarg (/ˈstuːlˌbɑːrɡ/ STOOL-barg; born July 5, 1968) is an American actor. He is known as a character actor, having portrayed a variety of roles in film, television, and theatre. He has received several awards, including nominations for two Primetime Emmy Awards, two Tony Awards, and a Golden Globe Award.

He rose to prominence as troubled university professor Larry Gopnik in the 2009 dark comedy film A Serious Man, directed by Joel and Ethan Coen. Stuhlbarg has since become known as a character actor and has appeared in numerous films and television series portraying real-life figures, such as George Yeaman in Lincoln (2012), Lew Wasserman in Hitchcock (2012), Andy Hertzfeld in Steve Jobs (2015), Edward G. Robinson in Trumbo (2015), Abe Rosenthal in The Post (2017), and Stanley Edgar Hyman in Shirley (2020). His other supporting roles include Hugo (2011), Men in Black 3 (2012), Blue Jasmine (2013), Pawn Sacrifice (2014), Arrival (2016), Call Me by Your Name and The Shape of Water (both 2017), and Bones and All (2022). He joined the Marvel Cinematic Universe, appearing as Nicodemus West in Doctor Strange (2016) and Doctor Strange in the Multiverse of Madness (2022).

On television, he portrayed Arnold Rothstein in HBO''s Boardwalk Empire (2010–2013), Richard A. Clarke in The Looming Tower (2018), and Richard Sackler in Dopesick (2021), receiving Primetime Emmy Award for Outstanding Supporting Actor in a Limited or Anthology Series or Movie nominations for the latter two. He also acted in FX''s Fargo (2017), Showtime''s Your Honour (2020–2023), and HBO''s The Staircase (2022). On stage, Stuhlbarg has acted in numerous productions, including the 2005 debut of Martin McDonagh''s The Pillowman on Broadway, for which he won a Drama Desk Award and received a Tony Award nomination. He returned to Broadway playing Boris Berezovsky in Peter Morgan''s Patriots (2024) and received a second Tony Award nomination for Best Actor in a Play.

Description above from the Wikipedia article Michael Stuhlbarg, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0836121', 1791590954, 1791590954);
