INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-88124', 88124, 'Jesse Plemons', '/og4I51GsuwohdPgoELOHVMMqMre.jpg', 'Acting', '1988-04-02', 'Dallas, Texas, USA', 'Jesse Lon Plemons (born April 2, 1988) is an American actor. He began his career as a child actor and achieved a breakthrough with his role as Landry Clarke in the NBC drama series Friday Night Lights (2006–2011). He subsequently portrayed Todd Alquist in season 5 of the AMC crime drama series Breaking Bad (2012–2013) and its sequel film El Camino: A Breaking Bad Movie (2019). He received his first Primetime Emmy Award nomination for his role as Ed Blumquist in season 2 of the FX anthology series Fargo (2015). He won a Critics'' Choice Television Award. He received a second Emmy nomination for his performance in "USS Callister", an episode of the anthology series Black Mirror (2017).

Plemons has acted in supporting roles in films such as The Master (2012), Bridge of Spies (2015), Game Night (2018), The Irishman (2019), Judas and the Black Messiah (2021) and Killers of the Flower Moon (2023). He starred in Other People (2016) and I''m Thinking of Ending Things (2020). For playing a rancher in The Power of the Dog (2021), he was nominated for the Academy Award for Best Supporting Actor, and for playing three roles in the anthology film Kinds of Kindness (2024), he won the Cannes Film Festival Award for Best Actor.', 'nm0687146', 1791590954, 1791590954);
