INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-31512', 31512, 'Robert John Burke', '/uWEaY5gypb6cp1bdUYG4uCKw4sK.jpg', 'Acting', '1960-09-12', 'New York City, New York, USA', 'Robert John Burke (born September 12, 1960) is an American actor known for his roles in the early films of Hal Hartley, as well as his roles in RoboCop 3 (1993), Tombstone (1993), and Thinner (1996). During the 2000s, Burke became well known for his portrayal of Mickey Gavin on Rescue Me (2004–11), Bart Bass in Gossip Girl (2007–12), Ed Tucker in Law & Order: Special Victims Unit (2002–20), and a number of other film and television roles including Intrusion (2021).

Description above from the Wikipedia article Robert John Burke, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0121559', 1791590954, 1791590954);
