INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2121005', 2121005, 'Emma D''Arcy', '/9Zlmb7VmtVCxkLq5yqFFRRxCaED.jpg', 'Acting', '1992-06-27', 'London, England, UK', 'Emma Zia D''Arcy (born 27 June 1992) is an English actor known for their roles in the BBC drama Wanderlust (2018), the Amazon Prime series Truth Seekers (2020), and the HBO fantasy series House of the Dragon (2022–present). They earned critical acclaim and two Golden Globe Award nominations for playing the lead role of Rhaenyra Targaryen in House of the Dragon. They have also appeared in the drama films Misbehaviour (2020) and Mothering Sunday (2021).

Description above from the Wikipedia article Emma D''Arcy, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm8458664', 1791590954, 1791590954);
