INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3115932', 3115932, 'Sophie Wilde', '/fMZvMsvTv9MYSC6LTNdIUaMGjIv.jpg', 'Acting', '1997-07-05', 'Sydney, New South Wales, Australia', 'Sophie Wilde (born 5 July 1997) is an Australian actress. She gained early attention for her roles on the Stan drama series Eden and the BBC One drama miniseries You Don''t Know Me (both 2021). Her performance in the horror film Talk to Me (2022) brought her further recognition, winning the AACTA Award for Best Actress in a Leading Role. She also received a nomination for the BAFTA Rising Star Award and was honoured with the Trophée Chopard.

Her other film roles include The Portable Door (2023) and Babygirl (2024). On television, she starred in the ITV period drama Tom Jones, and the Netflix series Everything Now (both 2023) and Boy Swallows Universe (2024). For the latter, Wilde received a Logie Award.

Description above from the Wikipedia article Sophie Wilde, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm12145223', 1791590954, 1791590954);
