INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-10182', 10182, 'Ving Rhames', '/tOVDvu1EQP78AwaUw6uh1wN818E.jpg', 'Acting', '1959-05-12', 'New York City, New York, USA', 'Irving Rameses Rhames (born May 12, 1959) is an American actor. He is best known for portraying IMF Agent Luther Stickell in the Mission: Impossible film series (1996–present) and crime boss Marsellus Wallace in Pulp Fiction (1994).', 'nm0000609', 1791590954, 1791590954);
