INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-19654', 19654, 'Michael Chiklis', '/pAkKjbzxP6Z6Y5zAGpwmWQo1iji.jpg', 'Acting', '1963-08-30', 'Lowell, Massachusetts, USA', 'Michael Charles Chiklis (/ˈtʃɪklɪs/; born August 30, 1963) is an American actor. He is best known for his role as Los Angeles Police Department (LAPD) Detective Vic Mackey on the FX police drama The Shield (2002–2008), for which he won the Primetime Emmy Award for Outstanding Lead Actor in a Drama Series in 2002 and was nominated in 2003.

Other starring television roles of his include Commissioner Tony Scali on the ABC police drama The Commish (1991–1996), Chris Woods in Daddio (2000), Jim Powell on the ABC science-fiction comedy-drama No Ordinary Family (2010–2011), Vincent Savino in the CBS crime drama Vegas (2012), Dell Toledo in American Horror Story: Freak Show (2014), and Nathaniel Barnes in Gotham (2015–2017). In film, he is best known for his roles as The Thing in two Fantastic Four films (2005–2007), George Callister in Eagle Eye (2008), Terry Eidson in When the Game Stands Tall (2014), and Father Dave in Hubie Halloween (2020).

Description above from the Wikipedia article Michael Chiklis, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0004821', 1791590954, 1791590954);
