INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1224188', 1224188, 'Brett Tucker', '/6IUQyy2pA8PRXX1MEx088JH6pcu.jpg', 'Acting', '1972-05-21', 'Melbourne, Victoria, Australia', 'Brett Alan Tucker (born May 21, 1972) is an Australian actor and singer. He was a series regular in The Saddle Club, McLeod''s Daughters, and Mistresses. He is also known for his role as Daniel Fitzgerald in Neighbours. He played Seattle Fire Battalion Chief Lucas Ripley on ABC''s TV series Station 19. He played Colin in the 2024 series of Troppo.', 'nm0875810', 1791590954, 1791590954);
