INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-217046', 217046, 'Eddie Baroo', '/pdxur3LhMEg8DNajEhHKE1J7FIx.jpg', 'Acting', '1968-09-25', 'Geelong, Victoria, Australia', 'Eddie Baroo (born Edmund Baroo, 25 September 1968 in Geelong, Victoria, Australia) – Australian actor, screenwriter, singer, and guitarist, frontman of the rock band Stodgewood.  He worked in the music industry for over a decade before transitioning to acting at age 30.  His most notable film roles include a Motorcycle Gang Member in Ghost Rider (2007, opposite Nicolas Cage and Eva Mendes), Bull in Australia (2008, Baz Luhrmann, opposite Nicole Kidman and Hugh Jackman), Willy in Red Hill (2010), Fourpack in Crawlspace (2012, which he also co-wrote), Merv in Son of a Gun (2014, opposite Ewan McGregor), Hammerhead Carney in Spin Out (2016), McMurdo in The Dry (2020, opposite Eric Bana), and Tom Evans in Sweet River (2020, which he also co-wrote).  On television he has appeared in Something in the Air (2001–2002), Underbelly (2008), Beaconsfield (2012), Fat Tony & Co. (2014), Black Sails (2016), Wolf Creek (2016), Mystery Road (2018), Mr Inbetween (2019), and Faraway Downs (2023).', 'nm1812267', 1791590954, 1791590954);
