INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-movie-1294189-rev-0', 'tmdb-movie-1294189', 'Sierbahnn', NULL, 'This is what Rambo First Blood would have been if he could have left and if he did have friends. It''s a movie about police overreach, the strange fascination that Americans have for their veterans and for the parallel justice systems that exist in the brothers of arms. It''s certainly not a bad movie and I enjoyed watching it even though it does make me feel very uneasy about the judicial and justice system of America when the action of this movie seems so relevant and so natural. Obviously Liam Neeson is miles ahead of anyone else in this movie and he only truly gets to act against a voice in a car which reminds me a bit about Night Rider I suppose. I think you''ll enjoy watching this movie. I certainly did.', '2026-09-03T11:28:11Z');
