INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1364004', 1364004, 'Tom Bateman', '/6elQzmY4EJHlLvHsaeoeo2dXOQ1.jpg', 'Acting', '1989-03-15', 'Oxford, Oxfordshire, England, UK', 'Tom Bateman is an English actor. He was born on 15 March 1989, to two teachers, one of fourteen children and has a twin brother. Brought up in Jericho in Oxford he attended Cherwell School before joining the National Youth Theatre and enrolling at the London Academy of Music and Dramatic Art, where he was awarded the Leverhulme Scholarship.', 'nm5290643', 1791590954, 1791590954);
