INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3234', 3234, 'Joan Cusack', '/59UIeHZFYrKyP20lXqijtfTXglO.jpg', 'Acting', '1962-10-11', 'New York City, New York, USA', 'Joanna "Joan" Mary Cusack is an American actress. An acclaimed character actress known for her distinctive voice and offbeat comedic timing, her portrayals of neurotic, endearing characters have earned her numerous accolades, including nominations for two Academy Awards and five Primetime Emmy Awards, winning once in 2015.

Cusack received nominations for the Academy Award for Best Supporting Actress for her roles in the comedy-drama Working Girl (1988) and the romantic comedy In & Out (1997). Her other starring roles include those in Toys (1992), Addams Family Values (1993), Nine Months (1995), Cradle Will Rock (1999), Where the Heart Is (2000), Looney Tunes: Back in Action (2003), School of Rock (2003), and Kit Kittredge: An American Girl (2008). She has also provided the voice of Jessie in the Toy Story franchise (1999–present), for which she won an Annie Award, and Abby Mallard in Chicken Little (2005).

Cusack was a cast member on the comedy sketch show Saturday Night Live from 1985 to 1986. She starred on the Showtime hit drama comedy series Shameless (2011–2015) as Sheila Jackson, a role for which she received five consecutive Primetime Emmy Award nominations, winning for the first time in 2015. She is the sister of actress Ann Cusack and actor John Cusack.', 'nm0000349', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1084244-cast-0', 'tmdb-movie-1084244', 'tmdb-person-3234', 'Jessie (voice)', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-31', 31, 'Tom Hanks', '/oFvZoKI6lvU03n4YoNGAll9rkas.jpg', 'Acting', '1956-07-09', 'Concord, California, USA', 'Thomas Jeffrey Hanks (born July 9, 1956) is an American actor and filmmaker. Known for both his comedic and dramatic roles, Hanks is one of the most popular and recognizable film stars worldwide, and is widely regarded as an American cultural icon.

Hanks made his breakthrough with leading roles in the comedies Splash (1984) and Big (1988). He won two consecutive Academy Awards for Best Actor for starring as a gay lawyer suffering from AIDS in Philadelphia (1993) and a young man with below-average IQ in Forrest Gump (1994). Hanks collaborated with film director Steven Spielberg on five films: Saving Private Ryan (1998), Catch Me If You Can (2002), The Terminal (2004), Bridge of Spies (2015), and The Post (2017), as well as the 2001 miniseries Band of Brothers, which launched him as a director, producer, and screenwriter.

Hanks'' other notable films include the romantic comedies Sleepless in Seattle (1993) and You''ve Got Mail (1998); the dramas Apollo 13 (1995), The Green Mile (1999), Cast Away (2000), Road to Perdition (2002), and Cloud Atlas (2012); and the biographical dramas Saving Mr. Banks (2013), Captain Phillips (2013), Sully (2016), and A Beautiful Day in the Neighborhood (2019). He has also appeared as the title character in the Robert Langdon film series, and has voiced Sheriff Woody in the Toy Story film series.

Description above from the Wikipedia article Tom Hanks, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000158', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-1084244-cast-1', 'tmdb-movie-1084244', 'tmdb-person-31', 'Woody (voice)', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-12898', 12898, 'Tim Allen', '/k8XPNHBO459FaqkqqM4tfX5GMKk.jpg', 'Acting', '1953-06-13', 'Denver, Colorado, USA', 'Timothy Alan Dick (born June 13, 1953), known professionally as Tim Allen, is an American actor and comedian. He is known for playing Tim "The Toolman" Taylor on the ABC sitcom Home Improvement (1991–1999) for which he won a Golden Globe Award as Mike Baxter on the ABC/Fox sitcom Last Man Standing (2011–2021). He voices Buzz Lightyear for the Toy Story franchise (1995–present) for which he won an Annie Award and played Scott Calvin and Santa Claus in The Santa Clause franchise (1994–2023).

Allen''s other films include Jungle 2 Jungle (1997), Galaxy Quest (1999), Joe Somebody (2001), Big Trouble (2002), Christmas with the Kranks (2004), The Shaggy Dog (2006), Wild Hogs (2007), The Six Wives of Henry Lefay (2009), and Crazy on the Outside (2010).

Description above from the Wikipedia article Tim Allen, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0000741', 1791590954, 1791590954);
