INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-81200', 81200, 'Conan O''Brien', '/deRbViPut0t80miscBpP2DhBJU5.jpg', 'Acting', '1963-04-18', 'Boston, Massachusetts, USA', 'Conan Christopher O''Brien (born April 18, 1963) is an American  television host, comedian, writer, producer and performer. He is  known for being the host of the late night shows: Late Night with Conan O''Brien (1993-2009), The Tonight Show with Conan O''Brien (2009-2010) and Conan (2010-2021), he is currently the host of the podcast Conan O''Brien needs a friend.

O''Brien was born in Brookline, Massachusetts and raised in an Irish  Catholic family. He landed his first comedy job as a writer for the  sketch comedy series Not Necessarily the News, after first serving as  president of the Harvard Lampoon while attending Harvard University.  After graduating, he moved to Los Angeles, where he wrote for several  comedy shows, and later moved to New York City to work on the writing  staff of Saturday Night Live, and later for The Simpsons. O''Brien went  on to serve as host of Late Night with Conan O''Brien from 1993 to 2009,  before going on to host the short-lived The Tonight Show with Conan  O''Brien for seven months. He is the only personality to ever serve as  host for both the NBC Late Night and Tonight Show franchises.

In 2010, it was announced that O''Brien would begin hosting a new late-night talk show on TBS called Conan, which ran from 2018 to 2021. During the time this show was in hiatus, he started the podcast Conan O''Brien needs a friend, which he hosts with his producer Matt Gourley and his assistant Sona Movsesian. Besides this, Conan also starred in Conan O''Brien Must Go, a series on Max in which he visits countries from around the world and meets up fans whom he talked to on the podcast.', 'nm0005277', 1791590954, 1791590954);
