INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-19487', 19487, 'Jay Hernandez', '/86mlhxglLYYCac1CWWj4s9uR9U9.jpg', 'Acting', '1978-02-20', 'Morelia, Michoacan, Mexico', 'Javier Manuel Hernandez Jr. (born February 20, 1978) is a Mexican-born American actor and fashion model. After making his television debut in NBC''s Hang Time, Hernandez made his film debut opposite Kirsten Dunst in the romantic drama Crazy/Beautiful (2001). He has since starred in numerous films, including Friday Night Lights (2004), Hostel (2005), Bad Moms (2016), and as Chato Santana / El Diablo in Suicide Squad (2016). He portrays Thomas Magnum in the CBS reboot of Magnum P.I.

