INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-24358', 24358, 'Lori Alan', '/cavATg4fX0zAl2MHwlt1IZei7EI.jpg', 'Acting', '1966-07-18', 'Potomac, Maryland, USA', 'Lori Alan (née Denniberg, born July 18, 1966) is an American actress, voice actress, writer, producer, and stand-up comedian. She voices the long-running role of Pearl Krabs the Whale on the animated series SpongeBob SquarePants. She also voices news anchor Diane Simmons on Family Guy, the Invisible Woman on Fantastic Four, and The Boss in the Metal Gear video game series, as well as various voices on Hey Arnold!.

She voiced for movies including Cloudy with a Chance of Meatballs, Inside Out, Monsters University, Despicable Me 2, Minions, and as Bonnie''s Mom in Toy Story 3, 4 and 5 (and Toy Story Toons).

She started acting at age five, making her television debut in a Shakey''s Pizza commercial. Her stage debut was as Annie''s youngest sister in a local community theater production of Annie Get Your Gun. A longtime member of New York''s Gotham City Improv (Groundlings East), she went on to Emerson College and graduated with honors from Tisch School of the Arts.', 'nm0015935', 1791590954, 1791590954);
