INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2823609', 2823609, 'Cooper Tomlinson', '/vBMQbYT1DyWPCUp11dIiqZR9zhd.jpg', 'Acting', '1999-01-11', 'Woodinville, Washington, USA', 'Cooper Tomlinson began his career as an actor/writer/producer developing short films in high school. After starring in and producing Aberdeen (2019). Cooper packed his bags for Los Angeles, briefly attending New York Film Academy where he met Curry Barker. The two dropped out of school and co-created the web series "Roommates" and the social media sketch comedy channel "That''s a Bad Idea" which as garnered over 1.5 million followers across Tik Tok, YouTube and Instagram and over 150 million views. In 2022, Tomlinson produced and starred in the found footage thriller "Milk & Serial" (2024) directed by Barker. He can be seen in Phil Gorn''s pandemic rom-com "A Wall Away" (2024).', 'nm7831367', 1791590954, 1791590954);
