INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-5423994', 5423994, 'Chloe Breen', '/oKBTQeGcQBM5aHNHwAqVWPjDVfz.jpg', 'Acting', '1999-11-24', NULL, 'Chloe Breen started acting at the young age of four after being cast in a local commercial for a community hospital. Since then, it has been her passion and her dream to entertain, enchant, enlighten, and make people laugh. Chloe respects the profession, at all levels, and right out of college, she worked as a PA on the film Down Low and worked closely with the cast, directors, producers and staff. Learning the business from behind the scenes right out of the gate gave Chloe a greater respect for all that goes into the making of a film.

More recently, Chloe has been cast in several horror/thriller films, where she has unfurled a new skill-set. Chloe has also been able to pivot quickly between roles and recently was cast as a lead in an independent Christmas comedy film. Bringing all her skills together, Chloe also landed a role in The Mask Reboot. Chloe feels blessed to be part of an industry that is evolving constantly and is eager to share her talent with the world. She credits her successes to date to her unflappable and incredible family who has supported and inspired her dream from the start.', 'nm11809205', 1791590954, 1791590954);
