INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3901', 3901, 'Richard Brake', '/JwsiErANShzPSdYsNoiNYdrSg1.jpg', 'Acting', '1964-11-30', 'Ystrad Mynach, Hengoed, Wales', 'Richard Colin Brake (born 30 November 1964) is a Welsh actor. Following his film debut in Death Machine (1994), Brake had a supporting role as Joe Chill in Batman Begins (2005). He subsequently appeared in numerous horror films such as Doom (2005), Hannibal Rising (2007), Mandy (2018), and Barbarian (2022), as well as his first lead role in Perfect Skin (2018). A frequent collaborator of Rob Zombie, Brake has appeared in four of his films: Halloween II (2009), 31 (2016), 3 from Hell (2019), and The Munsters (2022).', 'nm0104114', 1791590954, 1791590954);
