INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-5139', 5139, 'Robert Englund', '/cjGEkiavinHa1dnetDvnEhlD2Wm.jpg', 'Acting', '1947-06-06', 'Glendale, California, USA', 'Robert Barton Englund (born June 6, 1947) is an American actor and voice-actor, best known for playing the fictional serial killer Freddy Krueger, in the Nightmare on Elm Street film series. He received a Saturn Award nomination for Best Supporting Actor for A Nightmare on Elm Street 3: Dream Warriors in 1987 and A Nightmare on Elm Street 4: The Dream Master in 1988. Englund is a classically trained actor.', 'nm0000387', 1791590954, 1791590954);
