INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-185065', 185065, 'Emma Tate', '/in8SZAA5dG6wW1LBCU10j1J7W8V.jpg', 'Acting', '1971-10-30', 'London, England, UK', 'Emma Tate is a British voice actress. She is known for many roles including the voice of Perfect Peter in Horrid Henry, Harry in Harry and His Bucket Full of Dinosaurs, Raggles and Bluebird in Everything''s Rosie, Katsuma and Luvli in Moshi Monsters: The Movie, Kipper in The Magic Key and Gran in Kazoops.', 'nm1469295', 1791590954, 1791590954);
