INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-4438472', 4438472, 'Toni Olabanji', '/48XYJ3UBF2uIeeAO2e12vHg37yX.jpg', 'Acting', NULL, NULL, 'Growing up in Bermondsey, South London, Toni - known on the mic as BANJI - brings an unstoppable energy. Whether he’s commanding the screen as an actor or spitting bars as a rapper, he always delivers with fire. As a founding member of The Spit Game collective, BANJI honed his craft through raw cyphers, both in the studio and on the streets. Rooted in grime, he weaves in elements of jazz, hip-hop, and afrobeat to create a contemporary sound. His rapid flows and unique rhythms echo influences like Stormzy, Skepta, and JME, while bringing something fresh to the scene.

Beyond the music, BANJI leads rap clubs across London, empowering young people to own their culture, develop their skills, and, when needed, re-engage with education. In 2024, he was honored as Best Young Leader at the national Youth Music Awards for his impactful work. Now, as Associate Director of The Spit Game and Head of Rap Clubs, he continues to inspire.

On screen, Toni has starred in and co-produced two BAFTA-qualifying short films and has taken on diverse roles, from an upcoming Pinocchio horror film to projects exploring young Black male vulnerability.

Toni was once a student of, and is currently managed by, Turner.', NULL, 1791590954, 1791590954);
