INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1482026', 1482026, 'Scott Chambers', '/pANsw8kWaQzSwuVmr1Em5di9u4o.jpg', 'Acting', '2000-03-05', 'London, England, UK', 'Scott begun as an actor performing in films such as "Chicken", "Malevolent" for Netflix and "Doctor Jekyll" opposite Eddie Izzard. Under a second name - Scott Jeffrey - he has produced 114 Feature Films in the space of eight years with every single one being distributed worldwide. More recently "Winnie-The-Pooh: Blood and Honey" has gone viral with a cinema release in over 1500 screens in the US.', 'nm4500258', 1791590954, 1791590954);
