INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-37625', 37625, 'Andrew Garfield', '/5ydZ6TluPtxlz5G8nlWMB7SGmow.jpg', 'Acting', '1983-08-20', 'Los Angeles, California, USA', 'Andrew Russell Garfield (born 20 August 1983) is an English and American actor. He is known for his work across a variety of genres, from superhero films to musicals, in independent films. His accolades include a Tony Award, a British Academy Television Award, and a Golden Globe Award, in addition to nominations for two Academy Awards, three British Academy Film Awards, a Laurence Olivier Award, and a Primetime Emmy Award. Time magazine named him one of the 100 most influential people in the world in 2022. 

Garfield began his acting career on the West End stage and British television. His breakout roles came as a juvenile convict in the television film Boy A (2007) and later as Eduardo Saverin in David Fincher''s The Social Network (2010). Garfield achieved wider recognition for starring as the title character in Marc Webb''s Spider-Man films(2012–2014) and the Marvel Cinematic Universe(MCU) film Spider-Man: No Way Home (2021).

Garfield received Academy Award nominations for Best Actor for his performances as Desmond Doss in the war film Hacksaw Ridge (2016) and Jonathan Larson in the musical drama Tick, Tick... Boom! (2021). His other film credits include Never Let Me Go (2010), Silence (2016), Under the Silver Lake (2018), The Eyes of Tammy Faye (2021) and We Live in Time (2024). On television, he starred in the crime drama miniseries Under the Banner of Heaven (2022), which earned him a nomination for the Primetime Emmy Award for Outstanding Lead Actor in a Limited Series.

On stage, Garfield made his Broadway debut as Biff Loman in the revival of Death of a Salesman (2012), which earned him a nomination for the Tony Award for Best Featured Actor in a Play. For his performance as Prior Walter in the West End and Broadway revivals of Angels in America, he received a nomination for the Laurence Olivier Award for Best Actor. He later won the Tony Award for Best Actor in a Play.

Description above from the Wikipedia article Andrew Garfield, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1940449', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-0', 'tmdb-movie-977942', 'tmdb-person-37625', 'Ploughman', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-478', 478, 'Jamie Bell', '/xAfNYOJYOy5ee9PHbBF8Y6xzZ9I.jpg', 'Acting', '1986-03-14', 'Billingham, Stockton on Tees, England, UK', 'Andrew James Matfin Bell (born March 14, 1986) is an English actor. He rose to prominence for his debut role in Billy Elliot (2000), for which he won the BAFTA Award for Best Actor in a Leading Role, becoming one of the youngest winners of the award. He is also known for his leading roles as Tintin in The Adventures of Tintin (2011) and as Ben Grimm/Thing in Fantastic Four (2015).

Other notable performances include in the films King Kong (2005), Jumper (2008), Snowpiercer (2013), Rocketman (2019), and All of Us Strangers (2023). He earned a second BAFTA Award nomination for his leading performance in Film Stars Don''t Die in Liverpool (2017). In television, Bell starred as Abraham Woodhull in the AMC historical drama series Turn: Washington''s Spies (2014–2017).

Description above from the Wikipedia article Jamie Bell, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0068260', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-1', 'tmdb-movie-977942', 'tmdb-person-478', 'John Ball', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-8435', 8435, 'Stephen Dillane', '/qjIa6pXD4Z7nL7nH2LxyHDfxNgC.jpg', 'Acting', '1956-11-30', 'London, England, UK', 'Stephen Dillane (born 27 March 1957, Kensington, London) is a British actor. He is best known as Stannis Baratheon in Game of Thrones (2012–2015), Thomas Jefferson in John Adams (2008, Emmy-nominated), and DCI Karl Roebuck in The Tunnel (2013–2017, BAFTA-winning). He won a Tony Award for The Real Thing (2000). In film, he has appeared in Zero Dark Thirty (2012), Darkest Hour (2017), and Outlaw King (2018). He is married to Naomi Wirthner; his children include actor Frank Dillane, and his brother is Richard Dillane.', 'nm0226820', 1791590954, 1791590954);
