INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1945369', 1945369, 'Woody Norman', '/jQlx4bAGAmQfvzEuXw6A9cEmb95.jpg', 'Acting', '2009-03-12', 'Hampstead, London, England', 'Woody Ace Norman (born March 12, 2009) is an English actor. He is best known for his role as Jesse in the film C''mon C''mon (2021), for which he received a BAFTA nomination for Best Supporting Actor.', 'nm7035760', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-3', 'tmdb-movie-977942', 'tmdb-person-1945369', 'King Richard II', 3);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-2441', 2441, 'Tom Hollander', '/cqZiJsImFZ6TaeShRRg49AZ9TyT.jpg', 'Acting', '1967-08-25', 'Oxford, Oxfordshire, England, UK', 'Thomas Anthony Hollander (born 25 August 1967) is an English actor. He began his career in theatre, winning the Ian Charleson Award in 1992 for his performance as Witwoud in The Way of the World at the Lyric Hammersmith Theatre. He is known for his role in About Time, and in films such as Pirates of the Caribbean, In the Loop and Bohemian Rhapsody and drama films such as Enigma, Pride & Prejudice, Gosford Park, and Hanna, additionally portraying George V in The Lost Prince and The King''s Man. He co-wrote and played the lead role in the sitcom Rev., which won the British Academy Television Award for best sitcom in 2011. He also played the lead in the ITV''s Doctor Thorne and won the BAFTA Television Award for Best Supporting Actor for his role as Major Lance "Corky" Corkoran in the BBC series The Night Manager.

Description above from the Wikipedia article Tom Hollander, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0390903', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-4', 'tmdb-movie-977942', 'tmdb-person-2441', 'Treasurer Hales', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1363054', 1363054, 'Cosmo Jarvis', '/1kgghZ558CxZCJip5ufO6BAqUGp.jpg', 'Acting', '1989-09-01', 'Ridgewood, New Jersey, USA', 'Harrison Cosmo Krikoryan Jarvis is an English actor and singer-songwriter. He has starred in the films Lady Macbeth (2016), Calm with Horses (2019), and Persuasion (2022). In 2024, he portrayed John Blackthorne in the historical drama series Shōgun.

Description above from the Wikipedia article Cosmo Jarvis, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm4008605', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-5', 'tmdb-movie-977942', 'tmdb-person-1363054', 'Wat Tyler', 5);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1356758', 1356758, 'Thomasin McKenzie', '/WOpnEFG5Q8LWxP81MtUrskmVox.jpg', 'Acting', '2000-07-26', 'Wellington, New Zealand', 'Thomasin Harcourt McKenzie (born 26 July 2000) is an actress from New Zealand. After a minor role in The Hobbit: The Battle of Five Armies, she rose to critical prominece with the lead role in Debra Granik''s 2018 drama film Leave No Trace. After supporting roles in the 2019 films The King, Jojo Rabbit and True History of the Kelly Gang, as well as the 2021 thriller Old, Edgar Wright''s psychological horror film Last Night in Soho established her as one of the industry''s lead actresses.', 'nm5057169', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-6', 'tmdb-movie-977942', 'tmdb-person-1356758', 'Alyce', 6);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-9012', 9012, 'Jonny Lee Miller', '/otCQdDtnrMvZ5tPC62zLx0SaXeR.jpg', 'Acting', '1972-11-15', 'Kingston upon Thames, Surrey, England, UK', 'Jonathan Lee Miller (AKA Jonny) is an English actor who gained notoriety with roles in Hackers and Trainspotting.  The son and grandson of Stage and Film actors, Jonny''s first (uncredited) role was at age 10 in an episode of Doctor Who.  In 1996 he married Hacker''s costar Angelina Jolie, divorcing just 18 months later.  He later married and had one child with actress-model Michele Hicks.', 'nm0001538', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-movie-977942-cast-7', 'tmdb-movie-977942', 'tmdb-person-9012', 'Mayor Walworth', 7);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-77795', 77795, 'Katherine Waterston', '/zaqbXjr5jE1DnEoyAHokUDoCKOM.jpg', 'Acting', '1980-03-03', 'London, England, UK', 'Katherine Boyer Waterston is a British-American actress who has starred in films like Fantastic Beasts and Where to Find Them (2016) and Steve Jobs (2015). The daughter of actor Sam Waterston and model Lynn Louisa Woodruff, she studied acting at NYU''s Tisch School of the Arts. Waterston made her film debut in 2007 with roles in Michael Clayton and The Babysitters.', 'nm2239702', 1791590954, 1791590954);
