INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-25074', 25074, 'Stanley Townsend', '/ry1kek817WYHOh1npa3ojxmGJcI.jpg', 'Acting', '1961-08-20', 'Dublin, Ireland', 'Stanley Townsend (born August 1961) is an Irish actor. Townsend was born and brought up in Dublin. After attending Wesley College, Dublin, he studied mathematics and civil engineering at Trinity College. While there he joined the Dublin University Players, the college''s Amateur Dramatic Society. He later co-founded co-operative theatre company Rough Magic with writer/director Declan Hughes and theatre director Lynne Parker, performing in numerous productions including The Country Wife, Nightshade, and Sexual Perversity in Chicago. He subsequently went on to perform in several productions at The Gate and The Abbey Theatres in Dublin. In London, he has worked with such directors as Sam Mendes in The Plough and the Stars, Richard Eyre in Guys and Dolls and Rufus Norris in Under the Blue Sky. Theatre appearances at the Royal Court include The Alice Trilogy directed by Ian Rickson and Shining City directed by Conor McPherson, for which he won an Irish Theatre Award and was nominated for the Evening Standard Theatre Award for Best Actor in 2004.

Townsend''s television work began on a number of shows for RTÉ in Dublin. Since moving to London, television appearances have included Spooks, The Commander, Hustle, Waking the Dead, and Omagh Bombing.

ilm credits include Mike Newell''s Into the West, Jim Sheridan''s In the Name of the Father with Daniel Day-Lewis, The Van by Stephen Frears, Peter Greenaway''s The Tulse Luper Suitcases, The Libertine with Johnny Depp, Paul Morrison''s Wondrous Oblivion with Delroy Lindo, John Boorman''s The Tiger''s Tale and Michael Radford''s Flawless. He currently lives in London.', 'nm0870199', 1791590954, 1791590954);
