INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1862765', 1862765, 'Mutsuki Iwanaka', '/sf6pNjXI8uMUatZ5EhlZPWt8Xh5.jpg', 'Acting', '1994-01-07', 'Fukuoka, Japan', 'Mutsuki Iwanaka (岩中 睦樹, Iwanaka Mutsuki, born January 7, 1994) is a Japanese voice actor from Fukuoka Prefecture, Japan, affiliated with Mausu Promotion. He speaks the Kitakyushu and Hakata dialects.

After graduating from Fukuoka School of Music & Dance College in 2014, he joined the actor training center attached to Mausu Promotion. From around 2015, he appeared mainly as a background character in animes and games. He became affiliated with Mausu Promotion in April 1, 2016. In 2017, he got his first semi-regular character in the TV anime Tsuki ga Kirei in the role of Daisuke Tachibana.', 'nm8810414', 1791590954, 1791590954);
