INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1247604', 1247604, 'Agnez Mo', '/7GuBJxf5szQRCKLk3iG2ztfCo39.jpg', 'Acting', '1986-07-01', 'Jakarta, Indonesia', 'Agnes Monica Muljoto (born 1 July 1986), known professionally as Agnez Mo, is an Indonesian singer, songwriter, music producer, actress, dancer, model, and businesswoman. She started her career in the entertainment industry at the age of six as a child singer. In 2013, she signed a recording deal with the American label The Cherry Party, which is owned by Sony Music Entertainment. Her debut international single, Coke Bottle, was released indie in September 2013 and re-released in early 2014 by Sony Music, featuring American rappers Timbaland and T.I.', 'nm1296883', 1791590954, 1791590954);
