INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-59238', 59238, 'Christopher Rodriguez Marquette', '/8AL7UPXM4sVkOMgTHIxNdRi2SXP.jpg', 'Acting', '1984-10-03', 'Stuart, Florida, USA', 'Christopher Marquette (born October 3, 1984), also credited as Christopher Rodriguez-Marquette, is an American actor. He began his career with a main role as Adam Brody on the ABC sitcom Aliens in the Family (1996) before his breakout with a main role as Marc Delgado on the Lifetime medical drama series Strong Medicine (2000–2005).

Following his breakout on Strong Medicine, Marquette had a main role as Mason McAllister on the Fox soap opera Pasadena (2001) and voiced lead character Alex O''Connell on the WB animated series The Mummy (2001–2003). He gained further mainstream attention with a main role as Adam Rove on the CBS series Joan of Arcadia (2003–2005) and starring roles in the films Freddy vs. Jason (2003), The Girl Next Door (2004), Just Friends (2005), Alpha Dog (2006), and The Invisible (2007).

In the late 2000s, Marquette starred in the films Life During Wartime (2009), Race to Witch Mountain (2009), and Fanboys (2009). In the 2010s and 2020s, he starred in the films The Double (2011) and Always Watching: A Marble Hornets Story (2015) and had a main role as Octie on the Gala Film web series RZR (2024). In 2025, he was cast in the fourth season of Reacher.', 'nm0549815', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-108978-cast-4', 'tmdb-tv-108978', 'tmdb-person-59238', 'Jacob Merrick', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-18472', 18472, 'Kevin Corrigan', '/obSUGc68mQDvFONalMg25Xw5GZM.jpg', 'Acting', '1969-03-27', 'The Bronx, New York City, New York, USA', 'Kevin Fitzgerald Corrigan (born March 27, 1969) is an American actor. He has appeared mostly in independent films and television since the 1990s, including the role of Uncle Eddie on the sitcom Grounded for Life. His film appearances have included a supporting role in The Departed and co-starring roles in Big Fan and Results. Wikipedia', 'nm0180984', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-108978-cast-5', 'tmdb-tv-108978', 'tmdb-person-18472', 'Shaun Docherty', 5);
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-0', 'tmdb-tv-108978', 'charles338', NULL, 'Bought Reacher: Season 1 on Blu-Ray. I absolutely Loved the series and I hope Amazon will continue filming it. The actor that plays Reacher in the series "to me any way," fits closer to the description that Lee Child has in his books. Not to take anything away from Tom Cruise and the movies that he played Jack Reacher in, because he had a smaller frame. Both actors did a fantastic acting job in their films which I also have. Top class acting from both Alan Ritchson and Tom Cruise. I also have Lee Child''s books and if it wasn''t for him writing such fantastic novels we would not have these great films.', '2023-02-11T08:06:24Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-1', 'tmdb-tv-108978', 'misubisu', 8, 'Season one was a 10/10 show. I LOVED it.
I waited with eager anticipation for season two... and when I finally got to watch it, I was so disappointed.
In season one, Reacher was larger than life. In season two he just seemed les significant. Season two is 7/10. Still worth the watch, but just don''t expect the same va-va-voom that season one had.', '2024-01-20T05:58:47Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-2', 'tmdb-tv-108978', 'jw', 5, '## A tale of two Reachers
### a matter of taste.

_Disclaimer: I haven''t read the books._

You can re-cast characters, and play the same thing differently. That''s OK.

The Reacher we get in the Tom Cruise variant is perceptive, clever, cautious; he relies on his wits and knowledge of human nature. He does what he thinks necessary and right, tends to avoid collateral damage. He''s a loner, and perfectly fine with it.

The Reacher we get in the Alan Ritchson variant is a Hulk with penchant for killing; he leaves behind a trail of destruction and corpses. He pretends to be a loner, but is a lost team player in the end.

It''s like James Bond versus the A-Team. Both enjoyable, similar topics, but very different in tonality and production.


One more aspect: the Cruise-Reacher is like a modern Yojimbo.
The Ritchson one is written like a power fantasy: invincible avenger walks through walls to right the wrongs.


A matter of taste, really. I lost my appetite for this series in the second season.

PS: Season 1 is pretty much "Red Harvest" with a modern plot goal.', '2024-02-03T02:45:12Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-3', 'tmdb-tv-108978', 'cavemanharris', NULL, 'Season 1 of Reacher blew me away! Pure Jack Reacher - a one-man wrecking crew taking down bad guys. But season 2? Yikes. It felt like a cheap action movie showcasing a bunch of ex-military buddies instead. Lost the whole "lone wolf" vibe that made Reacher so cool. Should''ve called it "Reacher and the Misfit Battalion."', '2024-03-19T20:10:58Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-4', 'tmdb-tv-108978', 'Dean', 10, 'Great show. No propaganda and woke BS. Reacher is a great, big good guy. Show has likable characters and a lot of action. It''s much better than movie. Highly recommended!', '2025-09-12T19:11:41Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-108978-rev-5', 'tmdb-tv-108978', 'its.zeeshan5437404', NULL, '*Reacher* (2022) is such a great example of a series that gets the balance between action, mystery, and character development right. Alan Ritchson’s performance really makes Reacher feel like the larger-than-life character fans expect, while the investigation keeps the story moving. Definitely a must-watch for action and thriller fans.', '2026-08-20T07:21:06Z');
