INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-59941-rev-0', 'tmdb-tv-59941', 'AshenArcanist', 2, 'Fallon. What is there to say? He''s not funny, he''s not entertaining, and seemingly the only reason he has a show is backroom deals with whoever is making the horrible decision to keep him on the air -- even his memes are bad!

1 star is too much. Not recommended.', '2024-03-09T15:38:11Z');
