INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-141028', 141028, 'Johnny Carson', '/sSltRe7S82Zw29lMRGLeEoL2PUu.jpg', 'Acting', '1925-10-23', 'Corning, Iowa, USA', 'John William Carson (October 23, 1925 – January 23, 2005) was an American television host, comedian, writer, and producer. He is best known as the host of The Tonight Show Starring Johnny Carson (1962–1992). Carson received six Primetime Emmy Awards, the Television Academy''s 1980 Governor''s Award, and a 1985 Peabody Award. He was inducted into the Television Academy Hall of Fame in 1987. Carson was awarded the Presidential Medal of Freedom in 1992 and received a Kennedy Center Honor in 1993.', 'nm0001992', 1791590954, 1791590954);
