INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-6240', 6240, 'Mariska Hargitay', '/mF5BMaACeb1rlqp9Fz0f5z7N69H.jpg', 'Acting', '1964-01-23', ' Los Angeles, California, USA', 'Mariska Magdolna Hargitay (born January 23, 1964) is an American actress, producer, director and activist, best known for her role as New York City sex crimes Detective Olivia Benson on on the NBC television drama Law & Order: Special Victims Unit, a role that has earned her multiple awards and nominations, including an Emmy and Golden Globe.

The daughter of actress Jayne Mansfield and actor/bodybuilder Mickey Hargitay, Hargitay is a former beauty queen who made her film debut in the 1985 horror-comedy film Ghoulies, and her major television debut in the 1986 adventure drama series, Downtown. She appeared in numerous roles in film and television shows throughout the late 1980s and 1990s before being cast as Olivia Benson, a role that led to her founding the Joyful Heart Foundation, which provides support to women who have been sexually abused.', 'nm0002127', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-2734-cast-0', 'tmdb-tv-2734', 'tmdb-person-6240', 'Olivia Benson', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-21411', 21411, 'Ice-T', '/96TdPckI16ggfHcPrSFf6bHYLLe.jpg', 'Acting', '1958-02-16', 'Newark, New Jersey, USA', 'Tracy Morrow (born February 16, 1958), better known by his stage name Ice-T, is an American musician and actor.

He was born in Newark, New Jersey and moved to Crenshaw, Los Angeles, California when he was in the 7th grade. After graduating from high school he served in the United States Army for four years.

He began his career as a rapper in the 1980s and was signed to Sire Records in 1987, when he released his debut album Rhyme Pays. The next year, he founded the record label Rhyme Syndicate Records (named after his collective of fellow hip hop artists called the Rhyme Syndicate) and released another album, Power. He co-founded the thrash metal band Body Count, which he introduced in his 1991 album O.G.: Original Gangster. Body Count released its self-titled debut album in 1992. Ice-T encountered controversy over his track "Cop Killer", which was perceived to glamorize killing police officers. Ice-T asked to be released from his contract with Warner Bros. Records, and his next solo album, Home Invasion was released later in the Fall of 1993 through Priority Records. Body Count''s next album was released in 1994, and Ice-T released two more albums in the late 1990s.

Since 2000, he has portrayed NYPD Detective Odafin Tutuola on the NBC police drama Law & Order: Special Victims Unit.', 'nm0001384', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-2734-cast-1', 'tmdb-tv-2734', 'tmdb-person-21411', 'Odafin ''Fin'' Tutuola', 1);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-206637', 206637, 'Kelli Giddish', '/3zcqEyAguRhYofePyJehWm19uUX.jpg', 'Acting', '1980-04-13', 'Cumming, Georgia, USA', 'Kelli Giddish (born April 13, 1980) is an American television, stage, and film actress. Since 2011, she has played NYPD Detective Amanda Rollins in the NBC crime-drama television series Law & Order: Special Victims Unit. Giddish previously played Di Henry on the ABC soap opera All My Children (2005–2007), Dr. Kate McGinn in the Fox crime-drama series Past Life (2010), and Annie Nolan Frost in the NBC crime-drama series Chase (2010–2011).

Description above from the Wikipedia article Kelli Giddish, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm1534207', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-2734-cast-2', 'tmdb-tv-2734', 'tmdb-person-206637', 'Amanda Rollins', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1217599', 1217599, 'Peter Scanavino', '/kQzX89Ar4rEC1wwHcuDMr0YxUve.jpg', 'Acting', '1980-02-29', 'Denver, Colorado, USA', 'Peter Scanavino (born February 29, 1980) is an American actor.

Since 2005, Scanavino has had dozens of minor roles in films and on television, most notably Deception (2008), The Good Wife, and The Blacklist.

In 2005, Scanavino guest-starred on the NBC crime-drama series Law & Order: Criminal Intent in the fifth-season episode "Diamond Dogs" as petty criminal Johnny Feist. He was also a guest on Law & Order as a suspect who was a graphic designer in the 2009 episode "Just A Girl in the World".

In 2013, Scanavino guest-starred on the long-running NBC crime-drama series Law & Order: Special Victims Unit in Season 14, Episode 13, "Monster''s Legacy", as Johnny Dubcek. The same year, he starred in the independent romantic-comedy film Mutual Friends, directed by Matthew Watts.

In 2014, Scanavino joined SVU in its sixteenth season, this time as Dominick Carisi Jr., nicknamed Sonny, a new SVU detective. Initially in a recurring capacity, Scanavino was promoted to the main cast in the fifth episode of the same season. According to SVU Executive Producer Warren Leight, Carisi "comes in and shakes things up" and is "a guy who maybe needs a little bit of refining." Scanavino noted that Carisi is "a total outsider. He''s brusque and he doesn''t really get the nuances and he''s not very experienced so he puts his foot in his mouth a lot of times. But he''s learning. He''s picking it up. I think he''s a good detective, but he''s got a lot to learn on how to approach cases."

Scanavino starred in an episode of Netflix''s 2020 anthology series Social Distance as the father of his real-life son Leo Bai-Scanavino.', 'nm1813581', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-2734-cast-3', 'tmdb-tv-2734', 'tmdb-person-1217599', 'Dominick ''Sonny'' Carisi Jr.', 3);
