INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-2734-cast-6', 'tmdb-tv-2734', 'tmdb-person-1380500', 'Jake Griffin', 6);
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-2734-rev-0', 'tmdb-tv-2734', 'MovieGuys', 3, 'This series is a poster child for the way the US wants the world, to perceive its justice system.

Hard working, earnest police, backed by an imperfect but mostly well meaning, justice system. 

Of course, if you look behind the veil nothing could be further from the truth. The justice system and not just in the US, mind you is abusive and broken. More often than not failing victims and on a certain level, criminals, who often started out as victims of its indifference and outright cruelty.

I find long running series like this one annoying, in so much as they largely, shore up establishment narratives, rather than exposing them, for what they are.

Acting is reasonable but feels a little forced and unrealistic, at times. Its not helped by rather predictably, formulaic characterisations. 

In summary, I rate this series down not just because its somewhat formulaic and bland but because, in my view, it does the truth of the world we live in, a disservice. Things can only improve when reality is exposed for what it is, not buried beneath pro establishment, "the system mostly works" narratives.', '2024-08-17T23:29:34Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-2734-rev-1', 'tmdb-tv-2734', 'Nicki', 9, '**26 SEASONS** there''s a reason SVU is the longest-running primetime live-action series on American television. Every year this show is a must watch. The storylines are compelling and the actors are usually current, former or up-and-coming stars. Some "fans" have complained about the changing of cast members but I think it''s what keeps the show fresh. Hoping for many more seasons with Benson to come.', '2024-10-11T08:08:59Z');
INSERT OR REPLACE INTO title_videos (id, series_id, site, video_key, kind, name) VALUES ('tmdb-tv-2734-vid', 'tmdb-tv-2734', 'YouTube', 'MhGI_1DIhxw', 'Featurette', 'Benson and Stabler: A Look Back at a 25-Year Partnership | Law & Order: SVU | NBC');
