INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-58769', 58769, 'Stephen Colbert', '/zQ6pvfqIqYiV4TB7lDoaJL52H93.jpg', 'Acting', '1964-05-13', 'Washington, District of Columbia, USA', 'Stephen Tyrone Colbert (born May 13, 1964) is an American political satirist, writer, comedian, television host, and actor. He is the host of Comedy Central''s The Colbert Report, a satirical news show in which Colbert portrays a caricatured version of conservative political pundits.

Colbert originally studied to be an actor, but became interested in improvisational theatre when he met famed Second City director Del Close while attending Northwestern University. He first performed professionally as an understudy for Steve Carell at Second City Chicago; among his troupe mates were comedians Paul Dinello and Amy Sedaris, with whom he developed the critically acclaimed sketch comedy series Exit 57.

Colbert also wrote and performed on the short-lived Dana Carvey Show before collaborating with Sedaris and Dinello again on the cult television series Strangers with Candy. He gained considerable attention for his role on the latter as closeted gay history teacher Chuck Noblet. It was his work as a correspondent on Comedy Central''s news-parody series The Daily Show, however, that first introduced him to a wide audience.

In 2005, he left The Daily Show with Jon Stewart to host a spin-off series, The Colbert Report. Following The Daily Show''s news-parody concept, The Colbert Report is a parody of personality-driven political opinion shows such as The O''Reilly Factor. Since its debut, the series has established itself as one of Comedy Central''s highest-rated series, earning Colbert three Emmy Award nominations and an invitation to perform as featured entertainer at the White House Correspondents'' Association Dinner in 2006. Colbert was named one of Time''s 100 most influential people in 2006. His book I Am America (And So Can You!) was No. 1 on The New York Times Best Seller list.', 'nm0170306', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-63770-cast-0', 'tmdb-tv-63770', 'tmdb-person-58769', 'Self - Host', 0);
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-63770-rev-0', 'tmdb-tv-63770', 'Vlad Ulbricht', 2, 'Stephen Colbert was once a funny man. Now he''s an arrogant joke, not a funny one either.

That said, he is a brilliant businessperson. His unnecessarily childish but necessarily provocative rants against DT led to him edging out Fallon on ratings. Just as DT does not hate the press, he loves it and vice versa, Colbert (who strattles the position of comedian and political commentator) has a symbiotic relationship with his arch-nemesis, DT. Fallon is an annoying cunt, not funny at all. Triumph poops all over Conan. And while not very funny now, Stephen has become an excellent businessman -- ironic considering Trump''s media career was built using the same formula.', '2017-05-14T02:26:10Z');
