INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1284159', 1284159, 'Simon Baker', '/oay0Lo2zl0lJdguptxgx1BK9Xq7.jpg', 'Acting', '1969-07-30', 'Launceston, Tasmania, Australia', 'Simon Baker (born July 30, 1969) is an Australian actor and director. In his television acting career, he is best known for his lead role in the CBS television series The Mentalist as Patrick Jane and as Nicholas Fallin in The Guardian.

In his film acting career, he is best known for the lead role of Riley Denbo in Land of the Dead and Christian Thompson in the film adaptation of The Devil Wears Prada, based on the 2003 novel of the same name.

Simon Baker was born to a high school English teacher, Elizabeth Labberton, and a groundskeeper/mechanic, Barry Baker, on 30 July 1969, in Launceston, Tasmania. He was raised as a Roman Catholic. His parents divorced while he was still young. His mother later married Tom Denny, a butcher. Simon Baker also has a sister, currently a doctor in Australia, and three younger half brothers. By 1972, the family had moved from Launceston to Ballina, New South Wales, where Baker''s parents hoped to secure better paying jobs. In 1986, he graduated from Ballina High School as Simon Baker-Denny, after completing his primary school education at St. Francis Xavier Catholic Primary School, also in Ballina.', 'nm0048932', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-5920-cast-0', 'tmdb-tv-5920', 'tmdb-person-1284159', 'Patrick Jane', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-17346', 17346, 'Robin Tunney', '/vOmWyYNoVEaPPvoto4IW8dSXn7I.jpg', 'Acting', '1972-06-19', 'Chicago, Illinois, USA', 'Robin Tunney (born June 19, 1972) is an American actress. Tunney made her film debut in the comedy Encino Man (1992) and rose to prominence with leading roles in the cult films Empire Records (1995) and The Craft (1996). Her performance in Niagara, Niagara (1997) won her acclaim and the Volpi Cup for Best Actress. She had leading roles in the films End of Days (1999), Supernova and Vertical Limit (both 2000). Tunney earned critical acclaim for playing Veronica Donovan on Prison Break (2005–2006) and Teresa Lisbon on the television series The Mentalist (2008–2015).

Tunney was praised for her portrayal of a victim of sexual assault in the independent drama Open Window (2006). Her subsequent film roles across the 2000s include Cherish and The Secret Lives of Dentists (both 2002), The In-Laws (2003), Hollywoodland (2006), August and The Burning Plain (both 2008), and Passenger Side (2009). She led the thriller film Looking Glass (2018), and starred in the short-lived legal drama series The Fix (2019).', 'nm0000677', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-5920-cast-1', 'tmdb-tv-5920', 'tmdb-person-17346', 'Teresa Lisbon', 1);
