INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-5920-rev-0', 'tmdb-tv-5920', 'Rob', 9, 'This show takes four or five episodes to establish itself but once all the characters find their place and Simon Baker gets comfortable playing Jane you get utterly absorbed in this world. The mind games Jane plays are intriguing, the continuing Red John theme keeps you guessing and the uncertainty of trust in Jane''s motives adds perfect tension. Unfortunately, the expansion and revelation of Red John in the last seasons dilute the quality of the show somewhat.', '2023-06-01T13:04:47Z');
