INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1326172', 1326172, 'Lee Kwang-soo', '/eqjZXCV4EutnoVxZwOveK6Nl5W9.jpg', 'Acting', '1985-07-14', 'Namyangju, Gyeonggi, South Korea', 'Lee Kwang-soo (Korean: 이광수; born 14 July 1985) is a South Korean actor, entertainer, and model. He made his acting debut in the sitcom Here He Comes (2008). He then received further recognition for his roles in medical melodrama It''s Okay, That''s Love (2014), neo-noir film Confession (2014), black comedy film Collective Invention (2015), one-act play Puck! (2016), sitcom The Sound of Your Heart (2016) and drama Live (2018), drama comedy film Inseparable Bros (2019).

Besides acting, Lee is also known for being one of the regular cast members of the South Korean variety show Running Man since 2010.', 'nm4299091', 1791590954, 1791590954);
