INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-33238-rev-0', 'tmdb-tv-33238', 'Hnin@123', NULL, 'Running Man isn''t just a TV show anymore; it''s a comfort watch. While it may no longer have the frantic pace of its early years, it has matured into a witty, character-driven talk and game show. It’s the perfect "end-of-the-week" remedy that proves you don''t need a massive budget if you have a group of people who are willing to look like fools for a laugh.', '2026-05-15T14:54:06Z');
