INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-62856', 62856, 'Seth Meyers', '/nCcvpJFHWYHfu5oPxTOyA1uSdqA.jpg', 'Acting', '1973-12-28', 'Bedford, New Hampshire, USA', 'Seth Adam Meyers (born December 28, 1973) is an American comedian, writer, producer, actor, and television host. He hosts Late Night with Seth Meyers, a late-night talk show on NBC. Prior to that, he was a cast member and head writer for NBC''s Saturday Night Live (2001–2014) and hosted the show''s news parody segment, Weekend Update.', 'nm1024878', 1791590954, 1791590954);
