INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-61818-rev-0', 'tmdb-tv-61818', 'AshenArcanist', 1, 'From Letterman to Seth, Late Night has lost it''s way. Seth is boring, predictable and just not funny or entertaining. Moreover, he''s a poor interviewer who seems to do little to no research into his guests. It''s all self-aggrandizement where he is the focus.', '2024-01-24T13:19:52Z');
