INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-25544', 25544, 'James Pickens Jr.', '/iddDcaysDQ6IVMUjJ97Bv3lTBCu.jpg', 'Acting', '1954-10-26', 'Cleveland, Ohio, USA', 'James Pickens, Jr. (born October 26, 1954) is an American actor. He is best known for his starring role as Dr. Richard Webber on the ABC drama television series Grey''s Anatomy, and for his supporting role as Deputy Director Alvin Kersh on later seasons of the Fox Network science fiction series The X-Files.', 'nm0681782', 1791590954, 1791590954);
