INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-236021', 236021, 'Camilla Luddington', '/eKF5lSEdEtOCbsgb5mKjd8vYLck.jpg', 'Acting', '1983-12-15', 'Ascot, Berkshire, England, UK', 'Camilla Luddington (born 15 December 1983) is a British actress. Born and raised near London in Berkshire, England, her love of acting began when she started performing for her family and directing her younger brother at age 5. By 11 she had her first agent and appeared in local theatre productions. While continuing with theatre, she studied in the Theatre Arts program at the prestigious Italia Conti Academy in London, before coming to Hollywood in 2007.

Camilla burst into the acting world in the iconic role of Kate Middleton in the Lifetime movie "William and Kate." Airing the week of the Royal Wedding, the ratings were the second highest in Lifetime''s history, and the movie proved to be a worldwide success. Luddington portrays another iconic woman, Lara Croft, in the video game "Tomb Raider," produced by Crystal Dynamics. She was praised for giving "Tomb Raider" a much needed reboot. Within 48 hours of the game''s release in March of 2013, it sold over 1 million copies. Luddington had a major recurring role opposite David Duchovny and Evan Handler on the critically acclaimed Showtime series, "Californication," in 2012, portraying sweet English nanny Lizzie, an aspiring actress who would do whatever it takes to make it in L.A. In 2012 she also recurred on the award-winning HBO series "True Blood," as Claudette, a fairy who helps protects Sookie (Anna Paquin) and educates her on the world of fairies.

Luddington has appeared in various television series, including, "The Defenders," "CSI: Crime Scene Investigation," "The Forgotten," Nickelodeon''s "Big Time Rush" and "Days of our Lives." She co-wrote, co-directed and appeared in a short comedy "The Filming of Shakey Willis."

Luddington currently resides in Los Angeles.', 'nm2569832', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-1416-cast-4', 'tmdb-tv-1416', 'tmdb-person-236021', 'Jo Wilson', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-95475', 95475, 'Jason George', '/eTiyxcbtEsdANo1NGFsfk3mZPW3.jpg', 'Acting', '1972-02-09', 'Virginia Beach, Virginia, USA', 'Jason Winston George (born February 9, 1972) is an American actor and model. He is best known for his roles as Dr. Ben Warren on Grey''s Anatomy and its spinoff Station 19, Justin Russell in Breaking In, David in Kidnap, Detective Adam Noble on Lifetime''s fantasy series Witches of East End, Dominic Taylor on ABC''s drama Mistresses, Dr. Otis Cole on ABC''s Off the Map, Keith Bennett on ABC''s series Eli Stone, Jeremy on ABC''s drama What About Brian?, Jeremiah Thurgood "J.T." Hunter on UPN''s sitcom Eve, Kevin in Barbershop, Scott Littleton on NBC''s series Titans, and Michael Bourne on the NBC daytime soap opera Sunset Beach.', 'nm0313464', 1791590954, 1791590954);
