INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-232499', 232499, 'Harry Shum Jr.', '/xFQsThmdyuOk9jt3zgZL08ixf2b.jpg', 'Acting', '1982-04-28', 'Puerto Limón, Costa Rica', 'Harry Shum Jr. (born April 28, 1982) is a Costa Rican-American actor, singer, dancer, and choreographer. He is best known for his roles as Mike Chang on the Fox television series Glee (2009–15) and as Magnus Bane on the Freeform television series Shadowhunters (2016–19). He was nominated for four Screen Actors Guild Awards for his performance in Glee, winning once. He won the award for The Male TV Star of 2018 in the E! People''s Choice Awards for Shadowhunters.

Shum has appeared in the films Step Up 2: The Streets (2008), Step Up 3D (2010), White Frog (2012), Revenge of the Green Dragons (2014), Crouching Tiger, Hidden Dragon: Sword of Destiny (2016), Crazy Rich Asians (2018), the Hulu web series The Legion of Extraordinary Dancers (2010–2011) and the YouTube Originals series Single by 30 (2016). In 2020, he starred in Universal''s romantic drama All My Life.', 'nm1484270', 1791590954, 1791590954);
