INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-1416-rev-1', 'tmdb-tv-1416', 'GenerationofSwine', 1, 'Yeah, it''s like ER meets China Beach, and, as my dad classically said about China Beach "I don''t remember Vietnam being anything like that."

It''s really who is dating who in a hospital setting and we have seen both before in a myriad of different settings.

Unfortunately, sexual tension is really all the tension here, it''s the only source of actual drama. And after a season, it gets too much.', '2023-01-12T03:00:57Z');
