INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-27105', 27105, 'Ed Helms', '/gPZ8tZaNQGAc3KZRIPp9rgGbEnN.jpg', 'Acting', '1974-01-24', 'Atlanta, Georgia, USA', 'Edward "Ed" Parker Helms (born January 24, 1974) is an American comedian and actor. From 2002 to 2006, he was a correspondent on Comedy Central''s The Daily Show with Jon Stewart. He played paper salesman Andy Bernard in the NBC sitcom The Office (2006–2013), and starred as Stuart Price in The Hangover trilogy. He later starred in the comedy series Rutherford Falls (2021–2022), which he co-wrote.', 'nm1159180', 1791590954, 1791590954);
