INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-200', 200, 'Nancy Cartwright', '/kJQEz3NAwHGdb2sQzAnBf1RmMV4.jpg', 'Acting', '1957-10-25', ' Dayton, Ohio, USA', 'Nancy Campbell Cartwright (born October 25, 1957) is an American film and television actress, comedian and voice artist. She is best known for her long-running role as Bart Simpson on The Simpsons. She is also the aunt of pop star Sabrina Carpenter.', 'nm0004813', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-456-cast-2', 'tmdb-tv-456', 'tmdb-person-200', 'Bart Simpson / Maggie Simpson / Nelson Muntz / Ralph Wiggum (voice)', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-5586', 5586, 'Yeardley Smith', '/9AjPwbb3uz4GfgOPBYsy2ILvwkB.jpg', 'Acting', '1964-07-03', 'Paris, France', 'Martha Maria Yeardley Smith (/ˈjɑːrdli/ YARD-lee; born July 3, 1964) is an American actress. She stars as the voice of Lisa Simpson on the animated television series The Simpsons.

Smith began acting in 1982 after graduating from drama school. She moved to New York City in 1984, where she appeared in the Broadway production of Tom Stoppard''s The Real Thing. She made her film debut in 1985''s Heaven Help Us, followed by roles in The Legend of Billie Jean and Maximum Overdrive. She moved to Los Angeles in 1986 and took a recurring role in the television series Brothers.

In 1987, Smith auditioned for the Simpsons shorts on The Tracey Ullman Show. Smith intended to audition for the role of Bart Simpson, but the casting director felt her voice was too high, and she was cast as Bart''s sister Lisa. In 1989, the shorts were spun off into their own half-hour show, The Simpsons. For her work on The Simpsons, Smith received a Primetime Emmy Award for Outstanding Voice-Over Performance in 1992.

Alongside The Simpsons, Smith appeared in the sitcom Herman''s Head as Louise, and had recurring appearances as Marlene on Dharma & Greg and as Penny in two episodes of Dead Like Me. She has appeared in several films, including City Slickers, Just Write, Toys, and As Good as It Gets. In 2004, Smith performed an off-Broadway one-woman show entitled More at the Union Square Theatre in New York City. Aside from The Simpsons, Smith has recorded few voice-over parts, only commercials and the film We''re Back! A Dinosaur''s Story. Smith starred in and served as executive producer for the independent romantic comedy Waiting For Ophelia, which had its world premiere at the Phoenix Film Festival in April 2009.

Description above from the Wikipedia article Yeardley Smith, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0810379', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-456-cast-3', 'tmdb-tv-456', 'tmdb-person-5586', 'Lisa Simpson / Maggie Simpson (voice)', 3);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-5587', 5587, 'Hank Azaria', '/yFDw4b0jucuFWNnGcBPfpYUtn16.jpg', 'Acting', '1964-04-25', 'Queens, New York City, New York, USA', 'Henry Albert "Hank" Azaria (born April 25, 1964) is an American actor and producer. He is known for voicing many characters in the long-running animated sitcom The Simpsons since 1989, including Moe Szyslak, Chief Wiggum, Superintendent Chalmers, Comic Book Guy, Snake Jailbird, Professor Frink, Kirk Van Houten, Duffman, and formerly Apu Nahasapeemapetilon, Lou, Carl Carlson, among others. Azaria joined the show with little voice acting experience, but became a regular in its second season. For his work on the show, he has won four Primetime Emmy Awards.

Alongside his continued voice acting on The Simpsons, Azaria became more widely known through his live-action supporting appearances in films such as Quiz Show (1994), Heat, The Birdcage (1996) (for which he won a Screen Actors Guild Award) and Godzilla (1998). He has also appeared in numerous films including Mystery Men (1999), America''s Sweethearts (2001), Shattered Glass (2003), Along Came Polly (2004), Run Fatboy Run (2007), Night at the Museum: Battle of the Smithsonian (2009) and The Smurfs (2011) and The Smurfs 2 (2013). Further voice roles include Anastasia (1997), for which he won an Annie Award.

His live-action television work includes recurring roles on the sitcoms Mad About You and Friends, as well as dramatic roles in the TV films Tuesdays With Morrie (1999) as writer Mitch Albom and Uprising (2001) as Jewish resistance leader Mordechai Anielewicz. For the former, Azaria received the Primetime Emmy Award for Outstanding Supporting Actor in a Limited Series or Movie. He starred in the title roles in the Showtime drama series Huff (2004–2006) and the IFC sitcom Brockmire (2017–2020). His recurring role on the drama Ray Donovan earned him a sixth Primetime Emmy Award in 2016.

Azaria made his Broadway debut as Lancelot in Spamalot, for which he was nominated for the Tony Award for Best Actor in a Musical. He returned to Broadway in 2007, playing David Sarnoff in The Farnsworth Invention.', 'nm0000279', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-456-cast-4', 'tmdb-tv-456', 'tmdb-person-5587', 'Moe Szyslak / Chief Wiggum / Apu / Comic Book Guy / Carl Carlson / Superintendent Chalmers (voice)', 4);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-6008', 6008, 'Harry Shearer', '/wZpovXxQQqP7kxXPy2yj6QMbM55.jpg', 'Acting', '1943-12-23', 'Los Angeles, California, USA', 'Harry Julius Shearer (born December 23, 1943) is an American actor, comedian, musician, radio host, writer, and producer. Born in Los Angeles, California, Shearer began his career as a child actor. From 1969 to 1976, Shearer was a member of The Credibility Gap, a radio comedy group. Following the breakup of the group, Shearer co-wrote the film Real Life (1979) with Albert Brooks and worked as a writer on Martin Mull''s television series Fernwood 2 Night.

Shearer was a cast member on Saturday Night Live between 1979 and 1980, and 1984 and 1985. Shearer co-created, co-wrote and co-starred in the film This Is Spinal Tap (1984), a hit satirical rockumentary. In 1989, he joined the cast of the animated sitcom The Simpsons, providing voices for characters including Mr. Burns, Waylon Smithers, Ned Flanders, Reverend Lovejoy, Lenny Leonard, Kang, Principal Skinner, Kent Brockman, Otto Mann, Scratchy, and formerly Dr. Hibbert. Shearer has appeared in films including The Truman Show (1998) and A Mighty Wind (2003), and has directed two, Teddy Bears'' Picnic (2002) and The Big Uneasy (2010). Since 1983, Shearer has been the host of the public radio comedy/music program Le Show, incorporating satire, music, and sketch comedy. He has written three books.

Shearer has won a Primetime Emmy Award and has received several other Emmy and Grammy Award nominations. He has been married to singer-songwriter Judith Owen since 1993. He became an artist in residence at Loyola University, New Orleans in 2013.

Description above from the Wikipedia article Harry Shearer, licensed under CC-BY-SA, full list of contributors on Wikipedia.', 'nm0733427', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-456-cast-5', 'tmdb-tv-456', 'tmdb-person-6008', 'Ned Flanders / Mr. Burns / Smithers / Principal Skinner / Lenny Leonard (voice)', 5);
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-0', 'tmdb-tv-456', 'Thomaxz', 10, 'The awkward of Homer, and his family, and the endless stories.

Is fun, and of course Homer legendary expression "Do''h" with has been taking into the dictionary.

If you one of the few, who has been living under a rock, go see an episode.', '2017-03-11T22:24:39Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-1', 'tmdb-tv-456', 'dgood826', NULL, 'I don’t think this is the best episode of the Simpsons, it’s not even in the period most consider the best seasons (4-8), but it’s my favorite episode. It perfectly encapsulates what made the Simpsons amazing in the 90s: right amount of heart, wacky but not balls to the wall, and integrating a celebrity without it seeming like the episode was one long promo for that celebrity – fully understand the irony of that because he’s playing Michael Jackson in the episode. You can read more of my review here: https://imdgflicks.wordpress.com/2017/06/29/throwback-thursday-tv-review-simpsons-s3e01-stark-raving-dad/', '2017-06-30T15:53:11Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-2', 'tmdb-tv-456', 'MovieGuys', 4, 'Every now and again you find something hanging around in the back of the fridge or freezer you forgot to throw away. That''s how I feel about The Simpsons. 

Its humour is, in my opinion, long past its "use by" date, feeling stale and tired. Its a shame it hasn''t been shelved as what it did do back in the day, premiering on "The Tracey Ullman Show" (remember her?) was fantastic, witty and current. 

For myself I''d rather remember The Simpsons for what it was than what I believe its become. 4/10 from me.', '2019-04-01T22:05:00Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-3', 'tmdb-tv-456', 'Adam Rife', NULL, 'The Simpsons is my all time favorite show! I am 13, and I can relate in so many ways since the Simpsons are an average American family! My favorite character is Lisa because even though she feels lonely because of her smarts, she prevails and overcomes so many ...', '2020-09-08T16:33:48Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-4', 'tmdb-tv-456', 'GenerationofSwine', 5, 'To address the failing quality:

The Simpsons once mocked and then it became mainstream pop culture. So that is a cause of why it has declined.

And another cause is that there is a new PC comedy trend to laugh at things. As in the audience is expected to laugh at the object itself without having an actual joke behind it. As in, "This is a computer, Laugh at it!"

Because of that we see a transformation of the jokes. The celebrity guests were once the butt of the joke. Mulder and Scully came on and the Simpsons mocked them. Now the joke is the celebrity guest. As in, "This is Lady Gaga," or "this is Michelle Obama."

They aren''t spoofed or satirized in any way, the audience is just asked to laugh at the fact that they have a celebrity guest.

And the final reason is the laugh track comedy, in which the Simpsons has none. That is no laugh track. But now the writing sets up the jokes with almost a pause for laughter as if the tracks were there.

In the past the jokes were piled onto one another. There would be several jokes stacked right next to one another in a single event. Now it has become joke, pause to acknowledge the joke, continue.

But no ones really laughing because it''s no longer mocking culture, it''s no longer spoofing the celebrity guests, and it''s lost virtually all of its edge.', '2023-01-12T04:26:02Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-456-rev-5', 'tmdb-tv-456', 'Christian Sallay', 9, 'Despite a MAJOR decline in Quality, The Simpsons is still one of the greatest Television shows of all time. Its peaks are some of the highest out there, and it has been able to regain its footing as of late. Fantastic Series.', '2024-07-28T20:30:48Z');
