INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3497', 3497, 'Kyle Chandler', '/66n7XNj1dyYkzCBWR3Lq8Vz4PJ1.jpg', 'Acting', '1965-09-17', 'Buffalo, New York, USA', 'Kyle Martin Chandler (born September 17, 1965) is an American actor. He received critical acclaim for his performance as Eric Taylor in the NBC series Friday Night Lights(2006–2011), winning the Primetime Emmy Award for Outstanding Lead Actor in a Drama Series in 2011.

Making his screen acting debut in the 1988 television film Quiet Victory: The Charlie Wedemeyer Story, Chandler''s first regular television role was in the ABC drama Homefront (1991–1993). This was followed by the lead role of Gary Hobson in the series Early Edition (1996–2000). His well-received guest appearance on the medical drama Grey''s Anatomy (2006–2007) earned Chandler his first Primetime Emmy Award nomination.

Chandler''s film work has included notable supporting roles in King Kong (2005), The Day the Earth Stood Still (2008), Super 8 (2011), Argo, Zero Dark Thirty (both 2012), The Wolf of Wall Street (2013), Carol (2015), Manchester by the Sea (2016), Game Night and First Man (both 2018), Godzilla: King of the Monsters (2019), Godzilla vs. Kong (2021). Chandler has also starred in the Netflix thriller series Bloodline (2015–2017), for which he received further Primetime Emmy Award nominations.', 'nm0151419', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-95350-cast-0', 'tmdb-tv-95350', 'tmdb-person-3497', 'Hal Jordan / Halogram', 0);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1763709', 1763709, 'Aaron Pierre', '/hNwZWdT2KxKj1YLbipvtUhNjfAp.jpg', 'Acting', '1994-06-07', 'Bexley, London, England, UK', 'Aaron Stone Pierre (born 7 June 1994) is an English actor.

After training at the London Academy of Music and Dramatic Art, Pierre gained recognition for his role as Dev-Em in the science fiction series Krypton (2018–2019). He starred in the period drama miniseries The Underground Railroad (2021), and the thriller films Old (2021) and Rebel Ridge (2024). He also portrayed Malcolm X in the miniseries Genius and voiced Mufasa in Mufasa: The Lion King.', 'nm7543974', 1791590954, 1791590954);
