INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-95350-rev-1', 'tmdb-tv-95350', 'Horseface', 1, 'This is straight-up Hitler shit.

If you like Nazis and racism, this is just for you.

Jesus christ.', '2026-09-18T09:08:11Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-95350-rev-2', 'tmdb-tv-95350', 'Bud the Lea', 5, 'Rated 5 at most. Disappointing. I thought this was going to be good but after a LOT of talking (mumbling mainly) and occasionally meeting up with the woman sheriff who personally I wish was in the show a lot more because she''s badass and funny and basically interesting, I''ve now watched 3 whole episodes and all I can remember is the scene where Stewart as a kid has an apple on his head and his dad is taking shots at it like William Tell. That''s it. So maybe the kids love it cos the other guy flies into the air about once an episode, and the ring materialises green tinged objects for no particular reason, but really NOTHING HAPPENS. There''s no story. I feel I''m wasting my time, so I''m giving up. Rated 5 because I like the Stewart character.', '2026-09-21T18:17:43Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-95350-rev-3', 'tmdb-tv-95350', 'oktailmen07028', NULL, 'It''s just as I suspected fraud lantern (Hal Jordan) is still a fraud. Let''s just hope junior proves himself to be otherwise', '2026-10-04T21:01:09Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-95350-rev-4', 'tmdb-tv-95350', 'GenerationofSwine', 1, 'I mean I love how it takes the time to inject politics into it every few seconds and make the show about race politics and not, you know, about the Galactic Police that are the Lanterns.  Because what I''ve always said is "If only Hollywood would make more shows that pander to political ideologies," because at the end of the day, we are all tired of being entertained and want to be lectured like we are children who need the guidance of the dumbest people on earth not currently holding public office in Los Angeles.    
  
Yeah, it sucks, but you already knew that, just like you already knew that the only people actually going to praise it are the people that want politics over substance.', '2026-10-04T21:17:04Z');
INSERT OR REPLACE INTO title_reviews (id, series_id, author, rating, content, created_at) VALUES ('tmdb-tv-95350-rev-5', 'tmdb-tv-95350', 'caldot', NULL, 'Yall goofy. The show is good enough, this a light 8 I fuck with it 💯 something nice to sit down and watch every Sunday.', '2026-10-04T22:19:22Z');
