INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-1775259', 1775259, 'Ajay Nagrath', '/9WTV69QJJeFk0pDX8SVd1Ytmd70.jpg', 'Acting', '1986-02-16', 'Mumbai, Maharashtra, India', 'Ajay Nagrath is an Indian actor with a dynamic career spanning over three decades since 1992. Known for his versatility and screen presence, he has made a significant mark in both television and films. Ajay gained immense popularity through iconic roles in popular television shows like CID (as Inspector Pankaj, 2012–2018), Bade Achhe Lagte Hain 2 (as Aditya, 2021–2023), and classic family sitcoms like Shrimaan Shrimati (as Chintu), Family No. 1 (as Toofan), and Shakalaka Boom Boom (as Chandu).  He was also seen in shows like Biggest Loser Jeetega, Chashme Baddoor, Hukum Mere Aaka, and many more, demonstrating his ability to seamlessly adapt to diverse genres. In the film industry, Ajay has shared screen space with Bollywood legends in memorable films such as Pardes (with Shah Rukh Khan), Yeh Hai Jalwa (with Salman Khan and Rishi Kapoor), Ek Aur Ek Gyarah (with Govinda and Sanjay Dutt), Milenge Milenge (with Shahid Kapoor and Kareena Kapoor), and Kanoon (with Ajay Devgn), among others.  Ajay Nagrath is a passionate, dedicated, and deeply committed actor, constantly seeking engaging roles in films, web series, television serials, advertisements, and all forms of entertainment content. He brings a wealth of experience, charm, and authenticity to every role he plays.He is also the son of veteran actor and IMPPA (Indian Motion Picture Producers'' Association) Secretary, Anil Nagrath.

TMDB mini biography by: Ashvin Borad', 'nm1217389', 1791590954, 1791590954);
