INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-3417', 3417, 'Tony Goldwyn', '/A3hXimbzDtFxQ1PXNo8gG7RZeN4.jpg', 'Acting', '1960-05-20', 'Los Angeles, California, USA', 'Anthony Howard ''Tony'' Goldwyn (born May 20, 1960) is an American actor, singer, producer, director, and political activist. He''s known for his roles as Carl Bruner in Ghost, President Fitzgerald Grant on ABC''s drama Scandal, district attorney Nicholas Baxter on Law & Order, Gordon Gray in Oppenheimer, Paul Cohen in King Richard (2021), Andrew Prior in Divergent and Insurgent, Colonel Bagley in The Last Samurai,  Michael Drucker in The 6th Day, Dr. William ''Will'' Rudolph in Kiss the Girls, Neil Armstrong in the HBO miniseries From the Earth to the Moon, Harold Nixon in Nixon (1995), Fletcher Cole in The Pelican Brief, and the voice of Tarzan in the Disney animated Tarzan.

He made his acting debut appearing as Darren in the slasher film Friday the 13th Part VI: Jason Lives (1986), and had his breakthrough for starring as Carl Bruner in the fantasy thriller film Ghost (1990), which earned him a nomination for the Saturn Award for Best Supporting Actor. He went on to star as Harold Nixon in the biographical film Nixon (1995), which earned him a Screen Actors Guild Award nomination, and as Neil Armstrong in the HBO miniseries From the Earth to the Moon (1998).

He portrayed Paul Cohen in King Richard (2021), which earned him a second nomination for a Screen Actors Guild Award. He starred as President Fitzgerald Grant III in the ABC legal/political drama Scandal (2012–2018) and directed a number of episodes for the series, for which he won a Peabody Award.

He is the son of film producer Samuel Goldwyn Jr. and actress Jennifer Howard. His paternal grandparents were film producer and movie studio mogul Samuel Goldwyn, a Polish Jewish immigrant from Warsaw, and actress Frances Howard, who was originally from Nebraska. His maternal grandparents were playwright Sidney Howard and actress Clare Eames. His brother John Goldwyn is a film producer, a former executive of Paramount Pictures and the executive producer of the series Dexter. His brother Peter is also a film producer and the current President of Samuel Goldwyn Films. His half-sister Liz Goldwyn is a filmmaker. His niece is writer/producer Emily Goldwyn (John''s daughter - and her mother is actress Colleen Camp).

He has been married to production designer Jane Musky since 1987 and they have two daughters: Anna, a screenwriter, and Tess, an actress.', 'nm0001282', 1791590954, 1791590954);
INSERT OR REPLACE INTO cast_members (id, series_id, person_id, character_name, cast_order) VALUES ('tmdb-tv-549-cast-2', 'tmdb-tv-549', 'tmdb-person-3417', 'Nicholas Baxter', 2);
INSERT OR REPLACE INTO people (id, tmdb_id, name, photo_path, department, birthday, birthplace, bio, imdb_id, created_at, updated_at) VALUES ('tmdb-person-12791', 12791, 'Hugh Dancy', '/6UIiS3nxdNTbIo0G2kFNXpcDKhE.jpg', 'Acting', '1975-06-19', 'Staffordshire, England, UK', 'Hugh Michael Horace Dancy (born 19 June 1975) is an English actor who rose to prominence for his role as the title character in the television film adaptation of David Copperfield (2000) as well as for roles in feature films as Kurt Schmid in Black Hawk Down (2001) and Prince Charmont in Ella Enchanted (2004). Other film roles include Joe Conner in Shooting Dogs (2005), Grigg Harris in The Jane Austen Book Club (2007), Luke Brandon in Confessions of a Shopaholic (2009), Adam Raki in Adam (2009) and Ted in Martha Marcy May Marlene (2011). On television, he portrayed criminal profiler Will Graham in the NBC television series Hannibal (2013–2015), Cal Roberts in the Hulu original series The Path (2016–2018) and Robert Devereux, 2nd Earl of Essex, in the Channel 4 miniseries Elizabeth I (2005); the latter role earned him a Primetime Emmy Award nomination. Dancy currently portrays Senior Assistant District Attorney Nolan Price on NBC''s revival of the original Law & Order (2022–present).

